import { INCIDENT_DEFS } from '../data/IncidentDefs.js';

const SEVERITY_CONFIG = {
  critical: { icon: '\u26a0', color: 'red', bg: 'bg-red-500/10', border: 'border-red-500/20', text: 'text-red-400' },
  warning: { icon: '\u26a0', color: 'yellow', bg: 'bg-yellow-500/10', border: 'border-yellow-500/20', text: 'text-yellow-400' },
  info: { icon: '\u2139', color: 'blue', bg: 'bg-blue-500/10', border: 'border-blue-500/20', text: 'text-blue-400' },
};

const INVESTIGATION_STEPS = {};
for (const def of INCIDENT_DEFS) {
  if (def.investigationSteps && def.investigationSteps.length > 0) {
    INVESTIGATION_STEPS[def.name] = def.investigationSteps.map(step => ({
      label: step.hint,
      cmd: step.command.replace('<pod>', '{name}').replace('<node>', '{name}').replace('<service>', '{name}').replace('<policy>', '{name}').replace('<ingress>', '{name}').replace('<namespace>', '{name}'),
    }));
  }
}

export class IncidentPanel {
  constructor() {
    this.container = null;
    this.visible = false;
    this.incidents = [];
    this.nextId = 1;
    this.filter = 'active';
    this._boundToggle = this._onToggle.bind(this);
    this._boundIncident = this._onNewIncident.bind(this);
    this._boundCommandExecuted = this._onCommandExecuted.bind(this);
    this._requiredSteps = 2;
    this._timerInterval = null;
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'incident-panel';
    this.container.className = 'fixed top-12 left-0 w-80 bottom-0 z-30 transform -translate-x-full transition-transform duration-300 ease-out';
    this.container.innerHTML = this._buildHTML();
    document.body.appendChild(this.container);
    this._bindEvents();
    this._startTimers();
    this._loadInvestigationProgress();
  }

  _buildHTML() {
    return `
      <div class="h-full flex flex-col backdrop-blur-xl bg-white/5 border-r border-white/10 shadow-2xl">
        <div class="flex items-center justify-between px-4 py-3 border-b border-white/5">
          <div class="flex items-center gap-2">
            <svg class="w-4 h-4 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z"/>
            </svg>
            <span class="text-white/90 text-sm font-semibold">Incidents</span>
            <span id="incident-count" class="text-xs text-white/30 font-mono">0</span>
          </div>
          <button id="incident-close" class="p-1 text-white/30 hover:text-white/60 transition-colors">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
            </svg>
          </button>
        </div>

        <div class="flex border-b border-white/5">
          <button data-filter="active" class="flex-1 px-3 py-2 text-xs text-sky-400 border-b-2 border-sky-400 font-medium transition-colors">Active</button>
          <button data-filter="resolved" class="flex-1 px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors">Resolved</button>
          <button data-filter="all" class="flex-1 px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors">All</button>
        </div>

        <div id="incident-list" class="flex-1 overflow-y-auto scrollbar-thin p-3 space-y-2">
          <div class="text-white/20 text-sm text-center mt-8">No incidents reported</div>
        </div>
      </div>
    `;
  }

  _bindEvents() {
    document.getElementById('incident-close').addEventListener('click', () => this.hide());

    this.container.querySelector('[data-filter]').parentElement.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-filter]');
      if (btn) this._setFilter(btn.dataset.filter);
    });

    const engine = window.game?.engine;
    if (engine) {
      engine.on('ui:toggle-incidents', this._boundToggle);
      engine.on('incident:created', this._boundIncident);
      engine.on('command:raw', this._boundCommandExecuted);
    }
  }

  _startTimers() {
    this._timerInterval = setInterval(() => {
      if (this.visible) this._updateTimers();
    }, 1000);
  }

  _onToggle() {
    this.toggle();
  }

  _onNewIncident(data) {
    const incident = {
      id: this.nextId++,
      engineIncidentId: data.id || null,
      type: data.type || data.name || 'Unknown',
      severity: data.severity || 'warning',
      resource: data.resource || data.target || 'unknown',
      resourceUid: data.uid,
      message: data.message || data.description || 'An incident occurred',
      timestamp: Date.now(),
      status: 'active',
      resolvedAt: null,
      expanded: true,
      completedSteps: new Set(),
    };
    this.incidents.unshift(incident);
    window.game?.engine.emit('incident:count', { count: this._getActiveCount() });
    this.show();
    this._renderList();
  }

  addIncident(type, severity, resource, message, uid) {
    this._onNewIncident({ type, severity, resource, message, uid });
  }

  resolveIncident(id) {
    const incident = this.incidents.find(i => i.id === id);
    if (!incident || incident.status === 'resolved') return;
    incident.status = 'resolved';
    incident.resolvedAt = Date.now();

    const incidentEngine = window.game?.incidentEngine;
    if (incidentEngine && incident.engineIncidentId) {
      incidentEngine.resolveIncident(incident.engineIncidentId, 'manual');
    }

    window.game?.engine.emit('incident:resolved', { id, type: incident.type });
    window.game?.engine.emit('incident:count', { count: this._getActiveCount() });
    window.game?.engine.emit('xp:gain', { amount: this._getXPForResolve(incident) });
    if (this.visible) this._renderList();
  }

  _getXPForResolve(incident) {
    const elapsed = (incident.resolvedAt - incident.timestamp) / 1000;
    if (elapsed < 30) return 50;
    if (elapsed < 60) return 30;
    if (elapsed < 120) return 20;
    return 10;
  }

  _getActiveCount() {
    return this.incidents.filter(i => i.status === 'active').length;
  }

  _setFilter(filter) {
    this.filter = filter;
    this.container.querySelectorAll('[data-filter]').forEach(btn => {
      if (btn.dataset.filter === filter) {
        btn.className = 'flex-1 px-3 py-2 text-xs text-sky-400 border-b-2 border-sky-400 font-medium transition-colors';
      } else {
        btn.className = 'flex-1 px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors';
      }
    });
    this._renderList();
  }

  _emptyMessage() {
    if (this.filter === 'active') return 'No active incidents';
    if (this.filter === 'resolved') return 'No resolved incidents';
    return 'No incidents recorded';
  }

  _getFilteredIncidents() {
    if (this.filter === 'active') return this.incidents.filter(i => i.status === 'active');
    if (this.filter === 'resolved') return this.incidents.filter(i => i.status === 'resolved');
    return this.incidents;
  }

  _renderList() {
    const list = document.getElementById('incident-list');
    const filtered = this._getFilteredIncidents();

    document.getElementById('incident-count').textContent = this._getActiveCount();

    if (filtered.length === 0) {
      list.innerHTML = `<div class="text-white/20 text-sm text-center mt-8">${this._emptyMessage()}</div>`;
      return;
    }

    list.innerHTML = filtered.map(i => this._renderCard(i)).join('');
    this._bindCardEvents(list);
  }

  _renderCard(incident) {
    const config = SEVERITY_CONFIG[incident.severity] || SEVERITY_CONFIG.info;
    const steps = INVESTIGATION_STEPS[incident.type] || [];
    const elapsed = this._formatElapsed(Date.now() - incident.timestamp);
    const stars = this._getStarRating(incident);
    const completedCount = incident.completedSteps?.size || 0;
    const canResolve = steps.length === 0 || completedCount >= this._requiredSteps;

    return `
      <div class="rounded-lg border ${config.border} ${config.bg} overflow-hidden" data-incident-id="${incident.id}">
        <div class="px-3 py-2.5">
          <div class="flex items-start gap-2">
            <span class="text-sm ${config.text} mt-0.5">${config.icon}</span>
            <div class="flex-1 min-w-0">
              <div class="flex items-center gap-2">
                <span class="text-white/80 text-xs font-medium">${this._escapeHTML(incident.type)}</span>
                ${incident.status === 'active' ? `<span class="flex items-center gap-1"><svg class="w-3 h-3 text-amber-400 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6 6 0 10-12 0v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg></span>` : ''}
              </div>
              <div class="text-white/40 text-xs mt-0.5 truncate">${this._escapeHTML(incident.resource)}</div>
              <div class="text-white/30 text-[10px] mt-1">${this._escapeHTML(incident.message)}</div>
            </div>
            <div class="text-right shrink-0">
              <div class="text-white/20 text-[10px] font-mono incident-timer">${elapsed}</div>
              ${incident.status === 'resolved' ? `<div class="text-[10px] mt-0.5">${stars}</div>` : ''}
            </div>
          </div>

          ${incident.expanded && steps.length > 0 ? `
            <div class="mt-2 pt-2 border-t border-white/5">
              <div class="flex items-center justify-between mb-1.5">
                <div class="text-white/30 text-[10px] uppercase tracking-wider">Investigation</div>
                ${incident.status === 'active' ? `<div class="text-[10px] font-mono ${completedCount >= this._requiredSteps ? 'text-green-400' : 'text-white/30'}">${completedCount}/${steps.length} investigated</div>` : ''}
              </div>
              <div class="space-y-1">
                ${steps.map((step, idx) => {
                  const cmd = step.cmd.replace('{name}', incident.resource);
                  const done = incident.completedSteps?.has(idx);
                  return `
                    <div class="flex items-center gap-2 group">
                      <span class="text-[11px] w-4 text-center ${done ? 'text-green-400' : 'text-white/15'}">${done ? '\u2713' : '\u25CB'}</span>
                      <button class="flex-1 text-left px-2 py-1 text-[11px] font-mono ${done ? 'text-green-400/60 bg-green-400/5' : 'text-white/40 hover:text-white/60 bg-white/5 hover:bg-white/10'} rounded transition-colors run-cmd" data-cmd="${this._escapeHTML(cmd)}" title="Click to copy to command bar">
                        ${this._escapeHTML(step.label)}
                      </button>
                    </div>
                  `;
                }).join('')}
              </div>
            </div>
          ` : ''}

          <div class="flex items-center gap-2 mt-2">
            ${steps.length > 0 ? `
              <button class="toggle-expand text-[10px] text-white/30 hover:text-white/50 transition-colors">
                ${incident.expanded ? 'Hide steps' : 'Investigate'}
              </button>
            ` : ''}
            ${incident.status === 'active' ? (
              canResolve ? `
                <button class="resolve-btn ml-auto px-2 py-0.5 text-[10px] text-green-400 hover:bg-green-400/10 rounded transition-colors">
                  Resolve
                </button>
              ` : `
                <span class="ml-auto flex items-center gap-1 text-[10px] text-white/20" title="Run investigation commands first">
                  <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
                  Investigate first
                </span>
              `
            ) : `
              <span class="ml-auto text-[10px] text-green-400/50">Resolved</span>
            `}
          </div>
        </div>
      </div>
    `;
  }

  _bindCardEvents(list) {
    list.querySelectorAll('.toggle-expand').forEach(btn => {
      btn.addEventListener('click', () => {
        const card = btn.closest('[data-incident-id]');
        const id = parseInt(card.dataset.incidentId);
        const incident = this.incidents.find(i => i.id === id);
        if (incident) {
          incident.expanded = !incident.expanded;
          this._renderList();
        }
      });
    });

    list.querySelectorAll('.resolve-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const card = btn.closest('[data-incident-id]');
        const id = parseInt(card.dataset.incidentId);
        this.resolveIncident(id);
      });
    });

    list.querySelectorAll('.run-cmd').forEach(btn => {
      btn.addEventListener('click', () => {
        const cmd = btn.dataset.cmd;
        const cmdInput = document.getElementById('cmd-input');
        if (cmdInput) {
          const stripped = cmd.replace(/^kubectl\s+/, '');
          cmdInput.value = stripped;
          cmdInput.focus();
          const cmdBar = document.getElementById('command-bar');
          if (cmdBar?.classList.contains('translate-y-full')) {
            window.game?.engine.emit('ui:show-command-bar');
          }
        }
      });
    });
  }

  _getStarRating(incident) {
    if (incident.status !== 'resolved' || !incident.resolvedAt) return '';
    const elapsed = (incident.resolvedAt - incident.timestamp) / 1000;
    let stars = 1;
    if (elapsed < 30) stars = 3;
    else if (elapsed < 60) stars = 2;
    const filled = '\u2605'.repeat(stars);
    const empty = '\u2605'.repeat(3 - stars);
    return `<span class="text-amber-400">${filled}</span><span class="text-white/10">${empty}</span>`;
  }

  _formatElapsed(ms) {
    const secs = Math.floor(ms / 1000);
    if (secs < 60) return `${secs}s`;
    const mins = Math.floor(secs / 60);
    if (mins < 60) return `${mins}m ${secs % 60}s`;
    return `${Math.floor(mins / 60)}h ${mins % 60}m`;
  }

  _updateTimers() {
    const cards = this.container.querySelectorAll('[data-incident-id]');
    cards.forEach(card => {
      const id = parseInt(card.dataset.incidentId);
      const incident = this.incidents.find(i => i.id === id);
      if (incident && incident.status === 'active') {
        const timer = card.querySelector('.incident-timer');
        if (timer) timer.textContent = this._formatElapsed(Date.now() - incident.timestamp);
      }
    });
  }

  _escapeHTML(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  show() {
    this.visible = true;
    this.container.classList.remove('-translate-x-full');
    this.container.classList.add('translate-x-0');
    this._renderList();
  }

  hide() {
    this.visible = false;
    this.container.classList.remove('translate-x-0');
    this.container.classList.add('-translate-x-full');
  }

  toggle() {
    if (this.visible) this.hide();
    else this.show();
  }

  _onCommandExecuted(data) {
    const raw = (data.command || '').trim();
    if (!raw) return;
    const activeIncidents = this.incidents.filter(i => i.status === 'active');
    for (const incident of activeIncidents) {
      const steps = INVESTIGATION_STEPS[incident.type] || [];
      steps.forEach((step, idx) => {
        if (incident.completedSteps.has(idx)) return;
        const expanded = step.cmd.replace('{name}', incident.resource);
        const stepWithoutKubectl = expanded.replace(/^kubectl\s+/, '');
        if (this._fuzzyMatchCommand(raw, stepWithoutKubectl)) {
          incident.completedSteps.add(idx);
          window.game?.engine.emit('xp:gain', { amount: 10 });
        }
      });
    }
    if (this.visible) this._renderList();
    this._saveInvestigationProgress();
  }

  _fuzzyMatchCommand(userCmd, stepCmd) {
    const normalize = (s) => s.replace(/\s+/g, ' ').trim().toLowerCase();
    const u = normalize(userCmd);
    const s = normalize(stepCmd);
    if (u === s) return true;
    if (u.startsWith(s) || s.startsWith(u)) return true;
    const uParts = u.split(' ');
    const sParts = s.split(' ');
    if (uParts.length < 2 || sParts.length < 2) return false;
    if (uParts[0] !== sParts[0]) return false;
    if (uParts.length >= 2 && sParts.length >= 2 && uParts[1] === sParts[1]) {
      if (uParts.length >= 3 && sParts.length >= 3) {
        if (uParts[2].startsWith(sParts[2]) || sParts[2].startsWith(uParts[2])) return true;
      }
      if (uParts.length === 2 || sParts.length === 2) return true;
    }
    if (sParts.length >= 3) {
      const uPrefix = uParts.slice(0, sParts.length - 1).join(' ');
      const sPrefix = sParts.slice(0, -1).join(' ');
      if (uPrefix === sPrefix) return true;
    }
    const minLen = Math.min(uParts.length, sParts.length, 3);
    if (minLen >= 2) {
      const uJoined = uParts.slice(0, minLen).join(' ');
      const sJoined = sParts.slice(0, minLen).join(' ');
      if (uJoined === sJoined) return true;
    }
    return false;
  }

  _saveInvestigationProgress() {
    try {
      const data = this.incidents.map(i => ({
        id: i.id,
        completedSteps: Array.from(i.completedSteps || []),
        status: i.status,
      }));
      localStorage.setItem('k8sgames_investigation', JSON.stringify(data));
    } catch (e) {}
  }

  _loadInvestigationProgress() {
    try {
      const stored = localStorage.getItem('k8sgames_investigation');
      if (stored) {
        const data = JSON.parse(stored);
        for (const saved of data) {
          const incident = this.incidents.find(i => i.id === saved.id);
          if (incident && saved.completedSteps) {
            incident.completedSteps = new Set(saved.completedSteps);
          }
        }
      }
    } catch (e) {}
  }

  destroy() {
    const engine = window.game?.engine;
    if (engine) {
      engine.off?.('ui:toggle-incidents', this._boundToggle);
      engine.off?.('incident:created', this._boundIncident);
      engine.off?.('command:raw', this._boundCommandExecuted);
    }
    if (this._timerInterval) clearInterval(this._timerInterval);
    this.container?.remove();
  }
}

import { INCIDENT_DEFS, SEVERITY_LEVELS } from '../data/IncidentDefs.js';

const INCIDENT_STATE = {
  CREATED: 'Created',
  ACTIVE: 'Active',
  INVESTIGATING: 'Investigating',
  RESOLVED: 'Resolved'
};

class Incident {
  constructor(def, target, id) {
    this.id = id;
    this.defId = def.id;
    this.name = def.name;
    this.category = def.category;
    this.severity = def.severity;
    this.description = def.description;
    this.visualEffect = def.visualEffect;
    this.affectedResourceTypes = def.affectedResourceTypes;
    this.investigationSteps = def.investigationSteps.map((s) => ({ ...s, completed: false }));
    this.resolutionActions = [...def.resolutionActions];
    this.kubectlCommands = [...def.kubectlCommands];
    this.autoResolveTime = def.autoResolveTime;
    this.target = target;
    this.state = INCIDENT_STATE.CREATED;
    this.createdAt = Date.now();
    this.activatedAt = null;
    this.resolvedAt = null;
    this.investigationProgress = 0;
    this.cascadeChildren = [];
    this.cascadeParent = null;
    this.comboEligible = true;
  }

  activate() {
    this.state = INCIDENT_STATE.ACTIVE;
    this.activatedAt = Date.now();
  }

  startInvestigation() {
    if (this.state === INCIDENT_STATE.ACTIVE) {
      this.state = INCIDENT_STATE.INVESTIGATING;
    }
  }

  completeInvestigationStep(index) {
    if (index >= 0 && index < this.investigationSteps.length) {
      this.investigationSteps[index].completed = true;
      this.investigationProgress = this.investigationSteps.filter((s) => s.completed).length / this.investigationSteps.length;
    }
  }

  resolve() {
    this.state = INCIDENT_STATE.RESOLVED;
    this.resolvedAt = Date.now();
  }

  getResolutionTime() {
    if (!this.activatedAt || !this.resolvedAt) return null;
    return (this.resolvedAt - this.activatedAt) / 1000;
  }

  isExpired(currentTime) {
    if (!this.autoResolveTime || !this.activatedAt) return false;
    return (currentTime - this.activatedAt) / 1000 >= this.autoResolveTime;
  }
}

class IncidentEngine {
  constructor(gameEngine) {
    this.gameEngine = gameEngine;
    this.activeIncidents = new Map();
    this.resolvedIncidents = [];
    this.incidentCounter = 0;
    this.difficultyLevel = 1;
    this.spawnTimer = null;
    this.scriptedQueue = [];
    this.elapsedTime = 0;
    this.comboCount = 0;
    this.lastResolveTime = 0;
    this.comboWindow = 10000;
    this.maxCascadeDepth = 3;
    this.paused = false;

    this.pendingCascadeTimers = [];

    this.cascadeRules = new Map([
      ['NodeNotReady', [
        { incident: 'PodEviction', probability: 0.8, delay: 5000, severity: 2 },
        { incident: 'ServiceEndpointMissing', probability: 0.5, delay: 8000, severity: 3 }
      ]],
      ['OOMKilled', [
        { incident: 'ReadinessProbeFailure', probability: 0.6, delay: 3000, severity: 2 }
      ]],
      ['DNSResolutionFailure', [
        { incident: 'ServiceEndpointMissing', probability: 0.7, delay: 4000, severity: 3 },
        { incident: 'ReadinessProbeFailure', probability: 0.4, delay: 6000, severity: 2 }
      ]],
      ['EtcdLatency', [
        { incident: 'APIServerOverloaded', probability: 0.6, delay: 5000, severity: 5 },
        { incident: 'SchedulerFailure', probability: 0.4, delay: 8000, severity: 4 }
      ]],
      ['NodeDiskPressure', [
        { incident: 'PodEviction', probability: 0.7, delay: 10000, severity: 2 }
      ]],
      ['NodeMemoryPressure', [
        { incident: 'OOMKilled', probability: 0.6, delay: 5000, severity: 3 },
        { incident: 'PodEviction', probability: 0.5, delay: 8000, severity: 2 }
      ]]
    ]);

    this.difficultyWeights = this.buildDifficultyWeights();
  }

  buildDifficultyWeights() {
    const weights = new Map();
    for (let level = 1; level <= 10; level++) {
      const maxSeverity = Math.min(5, Math.ceil(level / 2));
      const eligible = INCIDENT_DEFS.filter((d) => d.severity <= maxSeverity);
      const totalWeight = eligible.reduce((sum, d) => sum + this._incidentWeight(level, d), 0);
      weights.set(level, eligible.map((d) => ({
        def: d,
        weight: this._incidentWeight(level, d) / totalWeight,
      })));
    }
    return weights;
  }

  _incidentWeight(level, def) {
    if (level >= def.severity * 2) return 3;
    if (level >= def.severity) return 2;
    return 1;
  }

  loadScriptedIncidents(incidents) {
    this.scriptedQueue = incidents
      .map((inc) => ({
        ...inc,
        def: INCIDENT_DEFS.find((d) => d.name === inc.type),
        triggered: false
      }))
      .filter((inc) => inc.def)
      .sort((a, b) => a.triggerTime - b.triggerTime);
  }

  start(mode) {
    this.mode = mode;
    this.elapsedTime = 0;
    this.paused = false;
    this.activeIncidents.clear();
    this.resolvedIncidents = [];
    this.comboCount = 0;
    this.incidentCounter = 0;

    if (this.spawnTimer) {
      clearInterval(this.spawnTimer);
    }

    this.spawnTimer = setInterval(() => this.tick(1000), 1000);
  }

  stop() {
    if (this.spawnTimer) {
      clearInterval(this.spawnTimer);
      this.spawnTimer = null;
    }
    this.paused = true;
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  tick(deltaMs) {
    if (this.paused) return;

    this.elapsedTime += deltaMs;
    const elapsedSeconds = this.elapsedTime / 1000;

    this.processScriptedIncidents(elapsedSeconds);
    this.processAutoResolve();
    this.updateActiveIncidents();

    if (this.mode === 'chaos') {
      this.processChaosTick(elapsedSeconds);
    }
  }

  processScriptedIncidents(elapsedSeconds) {
    for (const scripted of this.scriptedQueue) {
      if (scripted.triggered) continue;
      if (elapsedSeconds >= scripted.triggerTime) {
        scripted.triggered = true;
        let target = scripted.target;
        if (target === 'random' || target === 'multiple') {
          target = this.selectRandomTarget(scripted.def);
        }
        this.spawnIncident(scripted.def, target, scripted.severity || scripted.def.severity);
      }
    }
  }

  processAutoResolve() {
    const now = Date.now();
    for (const [id, incident] of this.activeIncidents) {
      if (incident.isExpired(now)) {
        this.resolveIncident(id, 'auto');
      }
    }
  }

  updateActiveIncidents() {
    for (const [, incident] of this.activeIncidents) {
      if (incident.state === INCIDENT_STATE.CREATED) {
        incident.activate();
        this.gameEngine.emit('incident:activated', {
          id: incident.id,
          name: incident.name,
          severity: incident.severity,
          target: incident.target,
          visualEffect: incident.visualEffect
        });
      }
    }
  }

  processChaosTick(elapsedSeconds) {
    const minutesElapsed = elapsedSeconds / 60;
    this.difficultyLevel = Math.min(10, 1 + Math.floor(minutesElapsed / 2));

    const baseInterval = 15;
    const interval = Math.max(3, baseInterval - this.difficultyLevel * 1.2);
    const shouldSpawn = Math.random() < (1 / interval);

    if (shouldSpawn && this.activeIncidents.size < 5 + this.difficultyLevel) {
      const def = this.selectRandomIncident();
      if (def) {
        const target = this.selectRandomTarget(def);
        this.spawnIncident(def, target);
      }
    }
  }

  selectRandomIncident() {
    const level = Math.min(10, this.difficultyLevel);
    const pool = this.difficultyWeights.get(level);
    if (!pool || pool.length === 0) return null;

    const roll = Math.random();
    let cumulative = 0;
    for (const entry of pool) {
      cumulative += entry.weight;
      if (roll <= cumulative) return entry.def;
    }
    return pool[pool.length - 1].def;
  }

  selectRandomTarget(def) {
    const state = this.gameEngine.cluster;
    if (!state) return 'unknown';

    const candidates = [];
    for (const kind of def.affectedResourceTypes) {
      const resources = state.getResourcesByKind(kind);
      if (resources) {
        candidates.push(...resources);
      }
    }

    if (candidates.length === 0) return 'unknown';
    return candidates[Math.floor(Math.random() * candidates.length)].name || 'unknown';
  }

  spawnIncident(def, target, overrideSeverity) {
    this.incidentCounter++;
    const id = `inc-${this.incidentCounter}`;

    const incident = new Incident(def, target, id);
    if (overrideSeverity) {
      incident.severity = overrideSeverity;
    }

    this.activeIncidents.set(id, incident);

    this.gameEngine.emit('incident:created', {
      id: incident.id,
      name: incident.name,
      category: incident.category,
      severity: incident.severity,
      description: incident.description,
      target: incident.target,
      visualEffect: incident.visualEffect,
      investigationSteps: incident.investigationSteps.map((s) => ({ command: s.command, hint: s.hint })),
      resolutionActions: incident.resolutionActions
    });

    this.checkCascade(incident, 0);

    return id;
  }

  checkCascade(parentIncident, depth) {
    if (depth >= this.maxCascadeDepth) return;

    const rules = this.cascadeRules.get(parentIncident.name);
    if (!rules) return;

    for (const rule of rules) {
      if (Math.random() > rule.probability) continue;

      const timer = setTimeout(() => {
        this.pendingCascadeTimers = this.pendingCascadeTimers.filter(t => t !== timer);
        if (this.paused) return;
        if (parentIncident.state === INCIDENT_STATE.RESOLVED) return;

        const childDef = INCIDENT_DEFS.find((d) => d.name === rule.incident);
        if (!childDef) return;

        const childId = this.spawnIncident(childDef, parentIncident.target, rule.severity);
        const child = this.activeIncidents.get(childId);
        if (child) {
          child.cascadeParent = parentIncident.id;
          parentIncident.cascadeChildren.push(childId);
          this.gameEngine.emit('incident:cascade', {
            parentId: parentIncident.id,
            childId: childId,
            parentName: parentIncident.name,
            childName: child.name
          });
          this.checkCascade(child, depth + 1);
        }
      }, rule.delay);
      this.pendingCascadeTimers.push(timer);
    }
  }

  investigateIncident(incidentId) {
    const incident = this.activeIncidents.get(incidentId);
    if (!incident) return null;

    incident.startInvestigation();

    this.gameEngine.emit('incident:investigating', {
      id: incident.id,
      name: incident.name,
      steps: incident.investigationSteps,
      commands: incident.kubectlCommands
    });

    return {
      steps: incident.investigationSteps,
      commands: incident.kubectlCommands,
      progress: incident.investigationProgress
    };
  }

  completeStep(incidentId, stepIndex) {
    const incident = this.activeIncidents.get(incidentId);
    if (!incident) return null;

    incident.completeInvestigationStep(stepIndex);

    this.gameEngine.emit('incident:step-completed', {
      id: incident.id,
      stepIndex,
      progress: incident.investigationProgress
    });

    return incident.investigationProgress;
  }

  resolveIncident(incidentId, actionId) {
    const incident = this.activeIncidents.get(incidentId);
    if (!incident) return null;

    incident.resolve();
    this.activeIncidents.delete(incidentId);
    this.resolvedIncidents.push(incident);

    const resolutionTime = incident.getResolutionTime();
    const severityInfo = SEVERITY_LEVELS.find((s) => s.level === incident.severity) || SEVERITY_LEVELS[0];
    let xpEarned = severityInfo.xpReward;

    const now = Date.now();
    if (now - this.lastResolveTime < this.comboWindow) {
      this.comboCount++;
      xpEarned = Math.floor(xpEarned * (1 + this.comboCount * 0.25));
    } else {
      this.comboCount = 1;
    }
    this.lastResolveTime = now;

    if (resolutionTime !== null && resolutionTime < 30) {
      xpEarned = Math.floor(xpEarned * 1.5);
    }

    const cascadeChildren = incident.cascadeChildren.filter((cid) => this.activeIncidents.has(cid));

    this.gameEngine.emit('incident:resolved', {
      id: incident.id,
      name: incident.name,
      severity: incident.severity,
      resolutionTime,
      action: actionId,
      xpEarned,
      combo: this.comboCount,
      cascadeChildrenRemaining: cascadeChildren.length
    });

    if (incident.cascadeChildren && incident.cascadeChildren.length >= 2) {
      this.gameEngine.emit('incident:cascading-resolved', { id: incident.id, cascadeCount: incident.cascadeChildren.length });
    }

    if (incident.name === 'SecretExposed') {
      this.gameEngine.emit('secret:exposed-fixed', { id: incident.id });
    }

    this.applyResolutionEffects(incident, actionId);

    return { xpEarned, combo: this.comboCount, resolutionTime };
  }

  applyResolutionEffects(incident, actionId) {
    const state = this.gameEngine.cluster;
    if (!state) return;

    switch (incident.name) {
      case 'CrashLoopBackOff':
      case 'ImagePullBackOff':
      case 'OOMKilled':
        this.gameEngine.emit('resource:healed', { target: incident.target, kind: 'Pod' });
        break;
      case 'NodeNotReady':
        this.gameEngine.emit('resource:healed', { target: incident.target, kind: 'Node' });
        break;
      case 'PodEviction':
        this.gameEngine.emit('resource:rescheduled', { target: incident.target });
        break;
      case 'DNSResolutionFailure':
        this.gameEngine.emit('cluster:dns-restored', {});
        break;
      case 'SecretExposed':
        this.gameEngine.emit('security:credential-rotated', { target: incident.target });
        break;
    }
  }

  getActiveIncidents() {
    return Array.from(this.activeIncidents.values()).map((inc) => ({
      id: inc.id,
      name: inc.name,
      category: inc.category,
      severity: inc.severity,
      state: inc.state,
      target: inc.target,
      visualEffect: inc.visualEffect,
      investigationProgress: inc.investigationProgress,
      createdAt: inc.createdAt,
      hasCascade: inc.cascadeChildren.length > 0
    }));
  }

  getIncidentDetails(incidentId) {
    const incident = this.activeIncidents.get(incidentId);
    if (!incident) return null;

    return {
      id: incident.id,
      name: incident.name,
      category: incident.category,
      severity: incident.severity,
      description: incident.description,
      state: incident.state,
      target: incident.target,
      visualEffect: incident.visualEffect,
      investigationSteps: incident.investigationSteps,
      resolutionActions: incident.resolutionActions,
      kubectlCommands: incident.kubectlCommands,
      investigationProgress: incident.investigationProgress,
      cascadeParent: incident.cascadeParent,
      cascadeChildren: incident.cascadeChildren,
      createdAt: incident.createdAt,
      activatedAt: incident.activatedAt
    };
  }

  getStats() {
    const total = this.resolvedIncidents.length;
    const avgResolveTime = total > 0
      ? this.resolvedIncidents.reduce((sum, inc) => sum + (inc.getResolutionTime() || 0), 0) / total
      : 0;

    const bySeverity = {};
    for (const inc of this.resolvedIncidents) {
      bySeverity[inc.severity] = (bySeverity[inc.severity] || 0) + 1;
    }

    const byCategory = {};
    for (const inc of this.resolvedIncidents) {
      byCategory[inc.category] = (byCategory[inc.category] || 0) + 1;
    }

    const cascadeCount = this.resolvedIncidents.filter((inc) => inc.cascadeChildren.length > 0).length;

    return {
      totalResolved: total,
      activeCount: this.activeIncidents.size,
      averageResolveTime: Math.round(avgResolveTime * 10) / 10,
      bySeverity,
      byCategory,
      cascadeCount,
      currentCombo: this.comboCount,
      difficultyLevel: this.difficultyLevel
    };
  }

  getClusterHealth() {
    let healthPenalty = 0;
    for (const [, incident] of this.activeIncidents) {
      const severityInfo = SEVERITY_LEVELS.find((s) => s.level === incident.severity);
      const multiplier = severityInfo ? (incident.severity / 5) : 0.2;
      healthPenalty += multiplier * 15;
    }
    return Math.max(0, Math.min(100, 100 - healthPenalty));
  }

  reset() {
    this.stop();
    for (const timer of this.pendingCascadeTimers) {
      clearTimeout(timer);
    }
    this.pendingCascadeTimers = [];
    this.activeIncidents.clear();
    this.resolvedIncidents = [];
    this.incidentCounter = 0;
    this.difficultyLevel = 1;
    this.comboCount = 0;
    this.lastResolveTime = 0;
    this.scriptedQueue = [];
    this.elapsedTime = 0;
  }

  destroy() {
    this.reset();
    this.gameEngine = null;
  }
}

