export class PersistentVolumeClaim extends ResourceBase {
  constructor(metadata = {}) {
    super('PersistentVolumeClaim', metadata);
    this.spec = {
      accessModes: metadata.accessModes || ['ReadWriteOnce'],
      resources: {
        requests: { storage: metadata.storageRequest || '10Gi' },
        limits: metadata.storageLimit ? { storage: metadata.storageLimit } : {}
      },
      storageClassName: metadata.storageClassName || 'standard',
      volumeName: metadata.volumeName || null,
      volumeMode: metadata.volumeMode || 'Filesystem',
      selector: metadata.selector || null
    };
    this.phase = 'Pending';
    this.boundVolume = null;
    this.capacity = null;
    this.bindingTimer = 0;
    this.bindingDelay = 1 + Math.random() * 3;
    this.mountedBy = [];
    this.usedBytes = 0;
    this.capacityBytes = parseStorage(this.spec.resources.requests.storage);
    this.conditions = [];
    this.setStatus('Pending');
  }

  _formatBytes(bytes) {
    if (bytes >= 1024 ** 4) return `${(bytes / 1024 ** 4).toFixed(1)}Ti`;
    if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)}Gi`;
    if (bytes >= 1024 ** 2) return `${(bytes / 1024 ** 2).toFixed(1)}Mi`;
    if (bytes >= 1024) return `${(bytes / 1024).toFixed(1)}Ki`;
    return `${bytes}`;
  }

  bind(volumeName) {
    this.phase = 'Bound';
    this.boundVolume = volumeName;
    this.capacity = { storage: this.spec.resources.requests.storage };
    this.conditions.push({
      type: 'Bound',
      status: 'True',
      lastTransitionTime: new Date().toISOString(),
      reason: 'Bound',
      message: `Bound to ${volumeName}`
    });
    this.addEvent('Normal', 'ProvisioningSucceeded', `Successfully provisioned volume ${volumeName}`);
    this.setStatus('Bound');
  }

  release() {
    this.phase = 'Released';
    this.boundVolume = null;
    this.setStatus('Released');
    this.addEvent('Normal', 'Released', `PVC released`);
  }

  markLost() {
    this.phase = 'Lost';
    this.setStatus('Lost');
    this.addEvent('Warning', 'VolumeLost', `Bound volume is no longer available`);
  }

  addMountReference(podName) {
    if (!this.mountedBy.includes(podName)) this.mountedBy.push(podName);
  }

  removeMountReference(podName) {
    this.mountedBy = this.mountedBy.filter(n => n !== podName);
  }

  getUsagePercent() {
    if (!this.capacityBytes) return 0;
    return (this.usedBytes / this.capacityBytes) * 100;
  }

  tick(deltaTime) {
    super.tick(deltaTime);

    if (this.phase === 'Pending') {
      this.bindingTimer += deltaTime;
      if (this.bindingTimer >= this.bindingDelay) {
        const pvName = `pv-${this.uid.substring(0, 8)}`;
        this.bind(pvName);
      }
    }

    if (this.phase === 'Bound' && this.mountedBy.length > 0) {
      this.usedBytes = Math.min(
        this.capacityBytes,
        Math.max(0, this.usedBytes + (Math.random() - 0.3) * this.capacityBytes * 0.005)
      );

      if (this.usedBytes >= this.capacityBytes * 0.9) {
        this.addEvent('Warning', 'VolumeNearFull', `Volume usage at ${this.getUsagePercent().toFixed(1)}%`);
      }
    }
  }

  getShape() { return 'cylinder'; }
  getColor() { return '#6b7280'; }

  toYAML() {
    return `apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
  labels:
${Object.entries(this.metadata.labels).map(([k, v]) => `    ${k}: "${v}"`).join('\n')}
spec:
  accessModes:
${this.spec.accessModes.map(m => `  - ${m}`).join('\n')}
  resources:
    requests:
      storage: ${this.spec.resources.requests.storage}
  storageClassName: ${this.spec.storageClassName}
  volumeMode: ${this.spec.volumeMode}
${this.spec.volumeName ? `  volumeName: ${this.spec.volumeName}` : ''}
status:
  phase: ${this.phase}
  accessModes:
${this.spec.accessModes.map(m => `  - ${m}`).join('\n')}
${this.capacity ? `  capacity:
    storage: ${this.capacity.storage}` : ''}`;
  }

  toDescribe() {
    return `Name:          ${this.metadata.name}
Namespace:     ${this.metadata.namespace}
StorageClass:  ${this.spec.storageClassName}
Status:        ${this.phase}
Volume:        ${this.boundVolume || '<none>'}
Labels:        ${Object.entries(this.metadata.labels).map(([k, v]) => `${k}=${v}`).join(', ')}
Annotations:   ${Object.entries(this.metadata.annotations).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>'}
Finalizers:    [kubernetes.io/pvc-protection]
Capacity:      ${this.capacity ? this.capacity.storage : '<pending>'}
Access Modes:  ${this.spec.accessModes.join(', ')}
VolumeMode:    ${this.spec.volumeMode}
Used By:       ${this.mountedBy.join(', ') || '<none>'}
Usage:         ${this._formatBytes(this.usedBytes)} / ${this.spec.resources.requests.storage} (${this.getUsagePercent().toFixed(1)}%)
Conditions:
${this.conditions.map(c => `  Type: ${c.type}  Status: ${c.status}  Reason: ${c.reason}`).join('\n') || '  <none>'}
Events:
${this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`).join('\n')}`;
  }
}

export class InspectorPanel {
  constructor() {
    this.container = null;
    this.resource = null;
    this.activeTab = 'overview';
    this.visible = false;
    this._boundSelect = this._onResourceSelected.bind(this);
    this._boundDeselect = this._onDeselect.bind(this);
    this._boundUpdate = this._onResourceUpdate.bind(this);
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'inspector-panel';
    this.container.className = 'fixed top-12 right-0 w-96 bottom-0 z-30 transform translate-x-full transition-transform duration-300 ease-out';
    this.container.innerHTML = this._buildShell();
    document.body.appendChild(this.container);
    this._bindGameEvents();
  }

  _buildShell() {
    return `
      <div class="h-full flex flex-col backdrop-blur-xl bg-white/5 border-l border-white/10 shadow-2xl">
        <div id="inspector-header" class="flex items-center justify-between px-4 py-3 border-b border-white/5">
          <div class="flex items-center gap-2 min-w-0">
            <div id="inspector-icon" class="w-8 h-8 rounded-lg bg-sky-500/20 flex items-center justify-center text-sky-400 text-sm font-bold shrink-0">P</div>
            <div class="min-w-0">
              <div id="inspector-name" class="text-white/90 text-sm font-semibold truncate">No Selection</div>
              <div id="inspector-subtitle" class="text-white/40 text-xs truncate">Select a resource</div>
            </div>
          </div>
          <div class="flex items-center gap-1 shrink-0">
            <button id="inspector-edit" class="hidden px-2 py-1 text-xs text-sky-400 hover:bg-sky-400/10 rounded transition-colors">Edit</button>
            <button id="inspector-close" class="p-1 text-white/30 hover:text-white/60 transition-colors">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
              </svg>
            </button>
          </div>
        </div>

        <div id="inspector-tabs" class="flex border-b border-white/5 px-2">
          <button data-tab="overview" class="px-3 py-2 text-xs text-sky-400 border-b-2 border-sky-400 font-medium transition-colors">Overview</button>
          <button data-tab="yaml" class="px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors">YAML</button>
          <button data-tab="events" class="px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors">Events</button>
          <button data-tab="describe" class="px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors">Describe</button>
        </div>

        <div id="inspector-body" class="flex-1 overflow-y-auto scrollbar-thin p-4">
          <div class="text-white/30 text-sm text-center mt-8">Select a resource to inspect</div>
        </div>
      </div>
    `;
  }

  _bindGameEvents() {
    document.getElementById('inspector-close').addEventListener('click', () => this.hide());

    document.getElementById('inspector-tabs').addEventListener('click', (e) => {
      const tab = e.target.closest('[data-tab]');
      if (tab) this._switchTab(tab.dataset.tab);
    });

    document.getElementById('inspector-edit').addEventListener('click', () => this._onEdit());

    const engine = window.game?.engine;
    if (engine) {
      engine.on('resource:selected', this._boundSelect);
      engine.on('resource:deselected', this._boundDeselect);
      engine.on('tick', this._boundUpdate);
    }
  }

  _onResourceSelected(data) {
    const cluster = window.game?.cluster;
    if (!cluster) return;
    this.resource = cluster.getResource(data.uid);
    if (this.resource) {
      this.show();
      this._renderHeader();
      this._renderTab();
    }
  }

  _onDeselect() {
    this.hide();
  }

  _onResourceUpdate() {
    if (!this.visible || !this.resource) return;
    const cluster = window.game?.cluster;
    if (!cluster) return;
    const updated = cluster.getResource(this.resource.metadata?.uid);
    if (updated) {
      this.resource = updated;
      if (this.activeTab === 'overview') this._renderTab();
    }
  }

  _renderHeader() {
    const r = this.resource;
    if (!r) return;
    const kind = r.kind || 'Unknown';
    const name = r.metadata?.name || 'unnamed';
    const ns = r.metadata?.namespace || 'default';
    const status = r.status?.phase || r.status?.state || 'Active';

    const iconMap = { Pod: 'P', Deployment: 'D', Service: 'S', Node: 'N', ConfigMap: 'C', Secret: 'K', Ingress: 'I', StatefulSet: 'SS', DaemonSet: 'DS' };
    const colorMap = {
      Pod: ['bg-sky-500/20', 'text-sky-400'],
      Deployment: ['bg-blue-500/20', 'text-blue-400'],
      Service: ['bg-purple-500/20', 'text-purple-400'],
      Node: ['bg-green-500/20', 'text-green-400'],
      ConfigMap: ['bg-amber-500/20', 'text-amber-400'],
      Secret: ['bg-red-500/20', 'text-red-400'],
      Ingress: ['bg-orange-500/20', 'text-orange-400'],
    };
    const [bgColor, textColor] = colorMap[kind] || ['bg-sky-500/20', 'text-sky-400'];

    document.getElementById('inspector-icon').className = `w-8 h-8 rounded-lg ${bgColor} flex items-center justify-center ${textColor} text-sm font-bold shrink-0`;
    document.getElementById('inspector-icon').textContent = iconMap[kind] || kind[0];
    document.getElementById('inspector-name').textContent = name;
    document.getElementById('inspector-subtitle').textContent = `${kind} / ${ns} / ${status}`;

    const editBtn = document.getElementById('inspector-edit');
    const editableKinds = ['Deployment', 'Service', 'ConfigMap', 'StatefulSet', 'DaemonSet', 'ReplicaSet', 'Secret', 'Pod', 'Ingress', 'NetworkPolicy', 'HorizontalPodAutoscaler'];
    if (editableKinds.includes(kind)) {
      editBtn.classList.remove('hidden');
    } else {
      editBtn.classList.add('hidden');
    }
  }

  _switchTab(tab) {
    this.activeTab = tab;
    document.querySelectorAll('#inspector-tabs [data-tab]').forEach(btn => {
      if (btn.dataset.tab === tab) {
        btn.className = 'px-3 py-2 text-xs text-sky-400 border-b-2 border-sky-400 font-medium transition-colors';
      } else {
        btn.className = 'px-3 py-2 text-xs text-white/40 border-b-2 border-transparent hover:text-white/60 transition-colors';
      }
    });
    this._renderTab();
  }

  _renderTab() {
    const body = document.getElementById('inspector-body');
    if (!this.resource) {
      body.innerHTML = '<div class="text-white/30 text-sm text-center mt-8">Select a resource to inspect</div>';
      return;
    }

    switch (this.activeTab) {
      case 'overview': body.innerHTML = this._renderOverview(); break;
      case 'yaml': body.innerHTML = this._renderYAML(); break;
      case 'events': body.innerHTML = this._renderEvents(); break;
      case 'describe': body.innerHTML = this._renderDescribe(); break;
    }
  }

  _renderOverview() {
    const r = this.resource;
    const kind = r.kind || 'Unknown';
    const statusColor = this._getStatusColor(r.status?.phase);

    let sections = `
      <div class="space-y-4">
        <div>
          <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Status</div>
          <div class="flex items-center gap-2">
            <div class="w-2 h-2 rounded-full ${statusColor}"></div>
            <span class="text-white/80 text-sm">${r.status?.phase || r.status?.state || 'Active'}</span>
          </div>
        </div>

        <div>
          <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Metadata</div>
          <div class="space-y-1.5">
            ${this._metaRow('Name', r.metadata?.name)}
            ${this._metaRow('Namespace', r.metadata?.namespace || 'default')}
            ${this._metaRow('UID', r.metadata?.uid)}
            ${this._metaRow('Created', this._formatTimestamp(r.metadata?.creationTimestamp))}
          </div>
        </div>

        <div>
          <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Labels</div>
          <div class="flex flex-wrap gap-1">
            ${Object.entries(r.metadata?.labels || {}).map(([k, v]) =>
              `<span class="px-2 py-0.5 text-xs bg-white/5 border border-white/10 rounded text-white/60">${this._escapeHTML(k)}=${this._escapeHTML(v)}</span>`
            ).join('') || '<span class="text-white/20 text-xs">No labels</span>'}
          </div>
        </div>

        <div>
          <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Annotations</div>
          <div class="space-y-1">
            ${Object.entries(r.metadata?.annotations || {}).map(([k, v]) =>
              `<div class="text-xs"><span class="text-white/40">${this._escapeHTML(k)}</span><span class="text-white/20">: </span><span class="text-white/60">${this._escapeHTML(v)}</span></div>`
            ).join('') || '<span class="text-white/20 text-xs">No annotations</span>'}
          </div>
        </div>
    `;

    if (kind === 'Pod') {
      sections += this._renderPodDetails(r);
    } else if (kind === 'Deployment') {
      sections += this._renderDeploymentDetails(r);
    } else if (kind === 'Service') {
      sections += this._renderServiceDetails(r);
    } else if (kind === 'Node') {
      sections += this._renderNodeDetails(r);
    }

    sections += '</div>';
    return sections;
  }

  _renderPodDetails(r) {
    const containers = r.spec?.containers || [{ name: 'main', image: 'unknown:latest' }];
    return `
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Containers</div>
        <div class="space-y-2">
          ${containers.map(c => `
            <div class="p-2 bg-white/5 rounded-lg border border-white/5">
              <div class="text-white/80 text-xs font-medium">${this._escapeHTML(c.name)}</div>
              <div class="text-white/40 text-xs mt-0.5">${this._escapeHTML(c.image || 'unknown')}</div>
              ${c.ports ? `<div class="text-white/30 text-xs mt-0.5">Ports: ${c.ports.map(p => p.containerPort).join(', ')}</div>` : ''}
            </div>
          `).join('')}
        </div>
      </div>
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Pod Info</div>
        <div class="space-y-1.5">
          ${this._metaRow('Node', r.spec?.nodeName || 'unscheduled')}
          ${this._metaRow('IP', r.status?.podIP || 'pending')}
          ${this._metaRow('Restarts', r.status?.restartCount || 0)}
          ${this._metaRow('QoS Class', r.status?.qosClass || 'BestEffort')}
        </div>
      </div>
    `;
  }

  _renderDeploymentDetails(r) {
    return `
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Deployment Info</div>
        <div class="space-y-1.5">
          ${this._metaRow('Replicas', `${r.status?.readyReplicas || 0}/${r.spec?.replicas || 0} ready`)}
          ${this._metaRow('Strategy', r.spec?.strategy?.type || 'RollingUpdate')}
          ${this._metaRow('Available', r.status?.availableReplicas || 0)}
          ${this._metaRow('Updated', r.status?.updatedReplicas || 0)}
        </div>
      </div>
    `;
  }

  _renderServiceDetails(r) {
    return `
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Service Info</div>
        <div class="space-y-1.5">
          ${this._metaRow('Type', r.spec?.type || 'ClusterIP')}
          ${this._metaRow('Cluster IP', r.spec?.clusterIP || '10.96.0.1')}
          ${this._metaRow('Ports', (r.spec?.ports || []).map(p => `${p.port}/${p.protocol || 'TCP'}`).join(', ') || '<none>')}
          ${this._metaRow('Selector', Object.entries(r.spec?.selector || {}).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>')}
        </div>
      </div>
    `;
  }

  _renderNodeDetails(r) {
    return `
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Node Info</div>
        <div class="space-y-1.5">
          ${this._metaRow('OS', r.status?.nodeInfo?.operatingSystem || 'linux')}
          ${this._metaRow('Architecture', r.status?.nodeInfo?.architecture || 'amd64')}
          ${this._metaRow('Kubelet', r.status?.nodeInfo?.kubeletVersion || 'v1.29.0')}
          ${this._metaRow('Container Runtime', r.status?.nodeInfo?.containerRuntimeVersion || 'containerd://1.7.0')}
        </div>
      </div>
      <div>
        <div class="text-white/30 text-xs uppercase tracking-wider mb-2">Capacity</div>
        <div class="space-y-1.5">
          ${this._metaRow('CPU', r.status?.capacity?.cpu || '4 cores')}
          ${this._metaRow('Memory', r.status?.capacity?.memory || '16Gi')}
          ${this._metaRow('Pods', r.status?.capacity?.pods || '110')}
        </div>
      </div>
    `;
  }

  _renderYAML() {
    const yaml = this._toYAML(this.resource, 0);
    return `
      <div class="bg-black/30 rounded-lg p-3 border border-white/5 overflow-x-auto">
        <pre class="text-xs font-mono leading-5 text-white/70">${yaml}</pre>
      </div>
    `;
  }

  _toYAML(obj, indent) {
    if (obj === null || obj === undefined) return `<span class="text-white/30">null</span>`;
    if (typeof obj === 'string') return `<span class="text-green-400">${this._escapeHTML(obj)}</span>`;
    if (typeof obj === 'number' || typeof obj === 'boolean') return `<span class="text-amber-400">${obj}</span>`;

    const prefix = '  '.repeat(indent);
    if (Array.isArray(obj)) {
      if (obj.length === 0) return `<span class="text-white/30">[]</span>`;
      return obj.map(item => `\n${prefix}<span class="text-white/30">-</span> ${this._toYAML(item, indent + 1)}`).join('');
    }

    const entries = Object.entries(obj);
    if (entries.length === 0) return `<span class="text-white/30">{}</span>`;

    return entries.map(([key, val]) => {
      const isComplex = val !== null && typeof val === 'object';
      if (isComplex) {
        return `\n${prefix}<span class="text-sky-400">${this._escapeHTML(key)}</span><span class="text-white/30">:</span>${this._toYAML(val, indent + 1)}`;
      }
      return `\n${prefix}<span class="text-sky-400">${this._escapeHTML(key)}</span><span class="text-white/30">:</span> ${this._toYAML(val, indent + 1)}`;
    }).join('');
  }

  _renderEvents() {
    const events = this.resource._events || this._generateSampleEvents();
    if (events.length === 0) {
      return '<div class="text-white/30 text-sm text-center mt-4">No events recorded</div>';
    }

    return `
      <div class="space-y-2">
        ${events.map(ev => `
          <div class="p-2 bg-white/5 rounded-lg border border-white/5">
            <div class="flex items-center gap-2 mb-1">
              <div class="w-1.5 h-1.5 rounded-full ${ev.type === 'Warning' ? 'bg-yellow-400' : 'bg-green-400'}"></div>
              <span class="text-white/60 text-xs font-medium">${this._escapeHTML(ev.reason)}</span>
              <span class="text-white/20 text-xs ml-auto">${this._escapeHTML(ev.timestamp)}</span>
            </div>
            <div class="text-white/40 text-xs pl-3.5">${this._escapeHTML(ev.message)}</div>
          </div>
        `).join('')}
      </div>
    `;
  }

  _generateSampleEvents() {
    const kind = this.resource.kind || 'Pod';
    const name = this.resource.metadata?.name || 'unknown';
    const now = new Date();

    if (kind === 'Pod') {
      return [
        { type: 'Normal', reason: 'Scheduled', message: `Successfully assigned default/${name} to node-1`, timestamp: this._timeAgo(now, 5) },
        { type: 'Normal', reason: 'Pulling', message: `Pulling image "${this.resource.spec?.containers?.[0]?.image || 'nginx:latest'}"`, timestamp: this._timeAgo(now, 4) },
        { type: 'Normal', reason: 'Pulled', message: 'Container image pulled successfully', timestamp: this._timeAgo(now, 3) },
        { type: 'Normal', reason: 'Created', message: 'Created container main', timestamp: this._timeAgo(now, 2) },
        { type: 'Normal', reason: 'Started', message: 'Started container main', timestamp: this._timeAgo(now, 1) },
      ];
    }
    if (kind === 'Deployment') {
      return [
        { type: 'Normal', reason: 'ScalingReplicaSet', message: `Scaled up replica set ${name}-7d6f4c8b to ${this.resource.spec?.replicas || 1}`, timestamp: this._timeAgo(now, 3) },
      ];
    }
    return [
      { type: 'Normal', reason: 'Created', message: `${kind} ${name} created successfully`, timestamp: this._timeAgo(now, 2) },
    ];
  }

  _renderDescribe() {
    const r = this.resource;
    const kind = r.kind || 'Unknown';
    const lines = [];

    lines.push(`Name:         ${r.metadata?.name}`);
    lines.push(`Namespace:    ${r.metadata?.namespace || 'default'}`);
    lines.push(`Kind:         ${kind}`);
    lines.push(`API Version:  v1`);
    lines.push(``);
    lines.push(`Labels:`);
    for (const [k, v] of Object.entries(r.metadata?.labels || {})) {
      lines.push(`              ${k}=${v}`);
    }
    if (!r.metadata?.labels || Object.keys(r.metadata.labels).length === 0) lines.push(`              <none>`);
    lines.push(`Annotations:`);
    for (const [k, v] of Object.entries(r.metadata?.annotations || {})) {
      lines.push(`              ${k}: ${v}`);
    }
    if (!r.metadata?.annotations || Object.keys(r.metadata.annotations).length === 0) lines.push(`              <none>`);
    lines.push(``);

    if (kind === 'Pod') {
      lines.push(`Status:       ${r.status?.phase || 'Pending'}`);
      lines.push(`IP:           ${r.status?.podIP || 'None'}`);
      lines.push(`Node:         ${r.spec?.nodeName || '<none>'}`);
      lines.push(``);
      lines.push(`Containers:`);
      for (const c of r.spec?.containers || [{ name: 'main', image: 'unknown' }]) {
        lines.push(`  ${c.name}:`);
        lines.push(`    Image:          ${c.image || 'unknown'}`);
        lines.push(`    Port:           ${c.ports ? c.ports.map(p => `${p.containerPort}/TCP`).join(', ') : '<none>'}`);
        lines.push(`    State:          ${r.status?.phase === 'Running' ? 'Running' : 'Waiting'}`);
        lines.push(`    Ready:          ${r.status?.phase === 'Running' ? 'True' : 'False'}`);
        lines.push(`    Restart Count:  ${r.status?.restartCount || 0}`);
      }
    } else if (kind === 'Deployment') {
      lines.push(`Replicas:     ${r.spec?.replicas || 0} desired | ${r.status?.readyReplicas || 0} ready | ${r.status?.availableReplicas || 0} available`);
      lines.push(`Strategy:     ${r.spec?.strategy?.type || 'RollingUpdate'}`);
      lines.push(`Selector:     ${Object.entries(r.spec?.selector?.matchLabels || {}).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>'}`);
    } else if (kind === 'Service') {
      lines.push(`Type:         ${r.spec?.type || 'ClusterIP'}`);
      lines.push(`IP:           ${r.spec?.clusterIP || 'None'}`);
      lines.push(`Port:         ${(r.spec?.ports || []).map(p => `${p.name || '<unnamed>'} ${p.port}/${p.protocol || 'TCP'}`).join(', ') || '<none>'}`);
      lines.push(`Selector:     ${Object.entries(r.spec?.selector || {}).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>'}`);
    } else if (kind === 'Node') {
      const ready = r.status?.conditions?.find(c => c.type === 'Ready');
      lines.push(`Status:       ${ready?.status === 'True' ? 'Ready' : 'NotReady'}`);
      lines.push(`Unschedulable: ${r.spec?.unschedulable ? 'true' : 'false'}`);
      lines.push(`Capacity:`);
      lines.push(`  cpu:        ${r.status?.capacity?.cpu || '4'}`);
      lines.push(`  memory:     ${r.status?.capacity?.memory || '16Gi'}`);
      lines.push(`  pods:       ${r.status?.capacity?.pods || '110'}`);
    }

    lines.push(``);
    lines.push(`Events:`);
    const events = this.resource._events || this._generateSampleEvents();
    lines.push(`  Type     Reason              Age    Message`);
    lines.push(`  ----     ------              ----   -------`);
    for (const ev of events) {
      lines.push(`  ${(ev.type || 'Normal').padEnd(9)}${(ev.reason || '').padEnd(20)}${(ev.timestamp || '').padEnd(7)}${ev.message || ''}`);
    }

    return `
      <div class="bg-black/30 rounded-lg p-3 border border-white/5 overflow-x-auto">
        <pre class="text-xs font-mono leading-5 text-white/70">${lines.map(l => this._escapeHTML(l)).join('\n')}</pre>
      </div>
    `;
  }

  _metaRow(label, value) {
    return `
      <div class="flex items-center text-xs">
        <span class="text-white/30 w-24 shrink-0">${this._escapeHTML(label)}</span>
        <span class="text-white/70 truncate">${this._escapeHTML(String(value ?? ''))}</span>
      </div>
    `;
  }

  _getStatusColor(phase) {
    const colors = { Running: 'bg-green-400', Ready: 'bg-green-400', Active: 'bg-green-400', Pending: 'bg-yellow-400', Failed: 'bg-red-400', CrashLoopBackOff: 'bg-red-400', Terminating: 'bg-orange-400' };
    return colors[phase] || 'bg-white/40';
  }

  _formatTimestamp(ts) {
    if (!ts) return 'Unknown';
    return new Date(ts).toLocaleString();
  }

  _timeAgo(now, minutesAgo) {
    return `${minutesAgo}m ago`;
  }

  _escapeHTML(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  _onEdit() {
    if (!this.resource) return;
    const kind = this.resource.kind;
    const name = this.resource.metadata?.name;
    window.game?.engine.emit('ui:edit-resource', { uid: this.resource.metadata?.uid, kind, name });
  }

  show() {
    this.visible = true;
    this.container.classList.remove('translate-x-full');
    this.container.classList.add('translate-x-0');
  }

  hide() {
    this.visible = false;
    this.container.classList.remove('translate-x-0');
    this.container.classList.add('translate-x-full');
    this.resource = null;
    window.game?.renderer?.deselectAll();
  }

  destroy() {
    const engine = window.game?.engine;
    if (engine) {
      engine.off?.('resource:selected', this._boundSelect);
      engine.off?.('resource:deselected', this._boundDeselect);
      engine.off?.('tick', this._boundUpdate);
    }
    this.container?.remove();
  }
}

const CHAOS_STATE = {
  IDLE: 'idle',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAME_OVER: 'gameOver'
};

const INITIAL_CLUSTER = {
  nodes: [
    { kind: 'Node', name: 'chaos-node-1', spec: { cpu: '8', memory: '16Gi', status: 'Ready' } },
    { kind: 'Node', name: 'chaos-node-2', spec: { cpu: '8', memory: '16Gi', status: 'Ready' } },
    { kind: 'Node', name: 'chaos-node-3', spec: { cpu: '8', memory: '16Gi', status: 'Ready' } }
  ],
  workloads: [
    { kind: 'Deployment', name: 'web-frontend', spec: { replicas: 2, image: 'nginx:latest' } },
    { kind: 'Deployment', name: 'api-backend', spec: { replicas: 2, image: 'node:18' } },
    { kind: 'Deployment', name: 'worker', spec: { replicas: 1, image: 'python:3.11' } },
    { kind: 'Service', name: 'web-svc', spec: { type: 'ClusterIP', port: 80 } },
    { kind: 'Service', name: 'api-svc', spec: { type: 'ClusterIP', port: 3000 } }
  ]
};

class ChaosMode {
  constructor(gameEngine, incidentEngine, scoringEngine) {
    this.gameEngine = gameEngine;
    this.incidentEngine = incidentEngine;
    this.scoringEngine = scoringEngine;
    this.ticker = null;
    this.pauseStart = 0;
    this.gameOverThreshold = 0;
    this._boundOnIncidentResolved = (data) => {
      if (this.state !== CHAOS_STATE.PLAYING) return;
      this.onIncidentResolved(data);
    };
    this.resetState();
  }

  resetState() {
    this.state = CHAOS_STATE.IDLE;
    this.survivalTime = 0;
    this.startTime = 0;
    this.pausedTime = 0;
    this.chaosBudget = 1;
    this.difficultyLevel = 1;
    this.totalXP = 0;
    this.incidentsResolved = 0;
    this.highestCombo = 0;
    this.clusterHealth = 100;
    this.healthDecayRate = 0;
    this.waveNumber = 0;
    this.waveIncidentCount = 0;
    this.waveCooldown = false;
    this.waveCooldownTimer = 0;
  }

  start() {
    this.resetState();
    this.state = CHAOS_STATE.PLAYING;
    this.startTime = Date.now();

    this.setupCluster();
    this.incidentEngine.reset();
    this.incidentEngine.start('chaos');

    this.ticker = setInterval(() => this.update(), 1000);

    this.gameEngine.on('incident:resolved', this._boundOnIncidentResolved);

    this.gameEngine.emit('chaos:started', {
      initialCluster: INITIAL_CLUSTER,
      difficultyLevel: this.difficultyLevel
    });
  }

  setupCluster() {
    const clusterState = this.gameEngine.cluster;
    if (!clusterState) return;

    clusterState.clear();

    const allResources = [...INITIAL_CLUSTER.nodes, ...INITIAL_CLUSTER.workloads];
    for (const resource of allResources) {
      clusterState.addResource({
        kind: resource.kind,
        name: resource.name,
        metadata: { name: resource.name, namespace: 'default', labels: {} },
        spec: resource.spec,
        status: { phase: 'Running' },
      });
    }
  }

  update() {
    if (this.state !== CHAOS_STATE.PLAYING) return;

    this.survivalTime = (Date.now() - this.startTime - this.pausedTime) / 1000;
    this.updateDifficulty();
    this.updateHealth();
    this.updateWaves();
    this.checkGameOver();

    this.gameEngine.emit('chaos:update', {
      survivalTime: Math.round(this.survivalTime),
      difficultyLevel: this.difficultyLevel,
      chaosBudget: Math.round(this.chaosBudget * 10) / 10,
      clusterHealth: Math.round(this.clusterHealth),
      activeIncidents: this.incidentEngine.getActiveIncidents().length,
      incidentsResolved: this.incidentsResolved,
      currentCombo: this.incidentEngine.comboCount,
      highestCombo: this.highestCombo,
      totalXP: this.totalXP,
      waveNumber: this.waveNumber
    });
  }

  updateDifficulty() {
    const minutesElapsed = this.survivalTime / 60;
    this.difficultyLevel = Math.min(10, 1 + Math.floor(minutesElapsed / 2));
    this.chaosBudget = 1 + (minutesElapsed * 0.5);
    this.healthDecayRate = this.difficultyLevel * 0.1;
  }

  updateHealth() {
    const activeIncidents = this.incidentEngine.getActiveIncidents();
    let penalty = 0;

    for (const incident of activeIncidents) {
      const severityPenalty = incident.severity * 2;
      const timeFactor = 1 + ((Date.now() - incident.createdAt) / 60000) * 0.5;
      penalty += severityPenalty * timeFactor;
    }

    penalty += this.healthDecayRate;

    const regenRate = this.incidentsResolved > 0 ? 0.5 : 0;
    this.clusterHealth = Math.max(0, Math.min(100, this.clusterHealth - (penalty / 60) + regenRate / 60));
  }

  updateWaves() {
    if (this.waveCooldown) {
      this.waveCooldownTimer -= 1;
      if (this.waveCooldownTimer <= 0) {
        this.waveCooldown = false;
        this.startNewWave();
      }
      return;
    }

    const minutesElapsed = this.survivalTime / 60;
    const waveInterval = Math.max(1, 3 - (this.difficultyLevel * 0.2));
    const expectedWave = Math.floor(minutesElapsed / waveInterval) + 1;

    if (expectedWave > this.waveNumber) {
      this.startNewWave();
    }
  }

  startNewWave() {
    this.waveNumber++;
    this.waveIncidentCount = Math.min(5, 1 + Math.floor(this.waveNumber / 3));

    this.gameEngine.emit('chaos:wave', {
      waveNumber: this.waveNumber,
      incidentCount: this.waveIncidentCount,
      difficultyLevel: this.difficultyLevel
    });

    this.waveCooldown = true;
    this.waveCooldownTimer = Math.max(5, 15 - this.difficultyLevel);
  }

  onIncidentResolved(data) {
    this.incidentsResolved++;
    this.totalXP += data.xpEarned || 0;
    this.highestCombo = Math.max(this.highestCombo, data.combo);

    const healthBonus = Math.min(10, data.severity * 2);
    this.clusterHealth = Math.min(100, this.clusterHealth + healthBonus);

    this.gameEngine.emit('chaos:incident-resolved', {
      xpEarned: data.xpEarned,
      combo: data.combo,
      healthRecovered: healthBonus,
      clusterHealth: Math.round(this.clusterHealth)
    });
  }

  checkGameOver() {
    if (this.clusterHealth <= this.gameOverThreshold) {
      this.gameOver();
    }
  }

  gameOver() {
    this.state = CHAOS_STATE.GAME_OVER;
    this.stopTicking();
    this.incidentEngine.stop();

    this.scoringEngine.recordChaosSurvival(this.survivalTime);

    const finalStats = {
      survivalTime: Math.round(this.survivalTime),
      difficultyReached: this.difficultyLevel,
      incidentsResolved: this.incidentsResolved,
      highestCombo: this.highestCombo,
      totalXP: this.totalXP,
      wavesReached: this.waveNumber,
      incidentBreakdown: this.incidentEngine.getStats()
    };

    this.gameEngine.emit('chaos:game-over', finalStats);
    this.gameEngine.emit('mode:game-over', {
      message: `Survived ${Math.round(this.survivalTime)}s | Wave ${this.waveNumber} | ${this.incidentsResolved} incidents resolved | Combo x${this.highestCombo}`
    });

    return finalStats;
  }

  pause() {
    if (this.state !== CHAOS_STATE.PLAYING) return;
    this.state = CHAOS_STATE.PAUSED;
    this.pauseStart = Date.now();
    this.incidentEngine.pause();
    this.gameEngine.emit('chaos:paused', { survivalTime: Math.round(this.survivalTime) });
  }

  resume() {
    if (this.state !== CHAOS_STATE.PAUSED) return;
    this.state = CHAOS_STATE.PLAYING;
    this.pausedTime += Date.now() - this.pauseStart;
    this.incidentEngine.resume();
    this.gameEngine.emit('chaos:resumed', {});
  }

  getStatus() {
    return {
      state: this.state,
      survivalTime: Math.round(this.survivalTime),
      difficultyLevel: this.difficultyLevel,
      chaosBudget: Math.round(this.chaosBudget * 10) / 10,
      clusterHealth: Math.round(this.clusterHealth),
      activeIncidents: this.incidentEngine.getActiveIncidents(),
      incidentsResolved: this.incidentsResolved,
      currentCombo: this.incidentEngine.comboCount,
      highestCombo: this.highestCombo,
      totalXP: this.totalXP,
      waveNumber: this.waveNumber
    };
  }

  stopTicking() {
    if (this.ticker) {
      clearInterval(this.ticker);
      this.ticker = null;
    }
  }

  restart() {
    this.stopTicking();
    this.incidentEngine.reset();
    this.start();
  }

  exit() {
    this.stopTicking();
    this.incidentEngine.stop();
    this.gameEngine.off('incident:resolved', this._boundOnIncidentResolved);
    this.state = CHAOS_STATE.IDLE;
    this.gameEngine.emit('chaos:exited', {});
  }

  destroy() {
    this.stopTicking();
    this.gameEngine?.off('incident:resolved', this._boundOnIncidentResolved);
    this.gameEngine = null;
    this.incidentEngine = null;
    this.scoringEngine = null;
  }
}

export { ChaosMode, CHAOS_STATE };

const DIFFICULTY_PRESETS = {
  easy: { label: 'Easy', description: 'Slower incidents, more resources', failureRate: 0.5, resourceMultiplier: 1.5 },
  normal: { label: 'Normal', description: 'Balanced experience', failureRate: 1.0, resourceMultiplier: 1.0 },
  hard: { label: 'Hard', description: 'Faster incidents, fewer resources', failureRate: 2.0, resourceMultiplier: 0.75 },
  nightmare: { label: 'Nightmare', description: 'Relentless chaos', failureRate: 3.0, resourceMultiplier: 0.5 },
};

const STORAGE_KEY = 'k8sgames_settings';

export class SettingsPanel {
  constructor() {
    this.container = null;
    this.visible = false;
    this.settings = this._loadSettings();
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'ingame-settings-panel';
    this.container.className = 'fixed inset-0 z-50 hidden';
    this.container.innerHTML = this._buildHTML();
    document.body.appendChild(this.container);
    this._bindEvents();
    this._applySettings();
  }

  _loadSettings() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) return JSON.parse(stored);
    } catch (e) {}
    return {
      difficulty: 'normal',
      showMinimap: true,
      showMetrics: false,
      cameraSpeed: 1.0,
      particleEffects: true,
      showConnectionLines: true,
      autoExpandIncidents: true,
      showHints: true,
      soundEnabled: false,
    };
  }

  _saveSettings() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.settings));
    } catch (e) {}
  }

  _buildHTML() {
    const diff = this.settings.difficulty;
    return `
      <div class="absolute inset-0 bg-black/60 backdrop-blur-sm" data-action="backdrop"></div>
      <div class="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[480px] max-h-[80vh] overflow-y-auto rounded-xl border border-white/10 bg-gray-900/95 backdrop-blur-xl shadow-2xl">
        <div class="flex items-center justify-between px-6 py-4 border-b border-white/5">
          <h2 class="text-white/90 text-base font-semibold">Settings</h2>
          <button data-action="close" class="p-1 text-white/30 hover:text-white/60 transition-colors">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
            </svg>
          </button>
        </div>

        <div class="px-6 py-4 space-y-6">
          <div>
            <div class="text-white/60 text-xs font-semibold uppercase tracking-wider mb-3">Difficulty</div>
            <div class="grid grid-cols-2 gap-2">
              ${Object.entries(DIFFICULTY_PRESETS).map(([key, preset]) => `
                <button class="settings-difficulty px-3 py-2 rounded-lg border text-left transition-all ${key === diff ? 'border-sky-500/50 bg-sky-500/10' : 'border-white/5 bg-white/5 hover:bg-white/10'}" data-difficulty="${key}">
                  <div class="text-sm font-medium ${key === diff ? 'text-sky-400' : 'text-white/70'}">${preset.label}</div>
                  <div class="text-[10px] text-white/30 mt-0.5">${preset.description}</div>
                </button>
              `).join('')}
            </div>
          </div>

          <div>
            <div class="text-white/60 text-xs font-semibold uppercase tracking-wider mb-3">Display</div>
            <div class="space-y-2">
              ${this._buildToggle('showMinimap', 'Show Minimap', 'Display cluster overview in bottom-right corner')}
              ${this._buildToggle('showConnectionLines', 'Connection Lines', 'Show ownership and networking lines between resources')}
              ${this._buildToggle('particleEffects', 'Particle Effects', 'Animated traffic particles along connections')}
              ${this._buildToggle('autoExpandIncidents', 'Auto-Expand Incidents', 'Automatically show investigation steps for new incidents')}
            </div>
          </div>

          <div>
            <div class="text-white/60 text-xs font-semibold uppercase tracking-wider mb-3">Gameplay</div>
            <div class="space-y-2">
              ${this._buildToggle('showHints', 'Show Hints', 'Display hints for campaign level objectives')}
            </div>
          </div>

          <div>
            <div class="text-white/60 text-xs font-semibold uppercase tracking-wider mb-3">Camera Speed</div>
            <div class="flex items-center gap-3">
              <input type="range" data-action="camera-speed" min="0.5" max="2.0" step="0.1" value="${this.settings.cameraSpeed}" class="flex-1 h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-sky-400">
              <span data-label="camera-speed-val" class="text-white/60 text-xs font-mono w-8">${this.settings.cameraSpeed}x</span>
            </div>
          </div>

          <div class="pt-2 border-t border-white/5">
            <div class="text-white/60 text-xs font-semibold uppercase tracking-wider mb-3">Data</div>
            <div class="flex gap-2">
              <button data-action="reset-progress" class="px-3 py-1.5 text-xs text-red-400 border border-red-500/20 rounded-lg hover:bg-red-500/10 transition-colors">Reset All Progress</button>
              <button data-action="export" class="px-3 py-1.5 text-xs text-white/50 border border-white/10 rounded-lg hover:bg-white/5 transition-colors">Export Save</button>
            </div>
          </div>
        </div>

        <div class="px-6 py-3 border-t border-white/5 flex justify-end">
          <button data-action="done" class="px-4 py-1.5 text-sm text-sky-400 bg-sky-400/10 rounded-lg hover:bg-sky-400/20 transition-colors font-medium">Done</button>
        </div>
      </div>
    `;
  }

  _buildToggle(key, label, description) {
    const checked = this.settings[key];
    return `
      <div class="flex items-center justify-between py-1.5">
        <div>
          <div class="text-white/70 text-sm">${label}</div>
          <div class="text-white/25 text-[10px]">${description}</div>
        </div>
        <button class="settings-toggle relative w-9 h-5 rounded-full transition-colors ${checked ? 'bg-sky-500' : 'bg-white/10'}" data-key="${key}">
          <div class="absolute top-0.5 ${checked ? 'left-[18px]' : 'left-0.5'} w-4 h-4 bg-white rounded-full shadow transition-all"></div>
        </button>
      </div>
    `;
  }

  _bindEvents() {
    const $ = (sel) => this.container.querySelector(sel);

    $('[data-action="backdrop"]').addEventListener('click', () => this.hide());
    $('[data-action="close"]').addEventListener('click', () => this.hide());
    $('[data-action="done"]').addEventListener('click', () => this.hide());

    this.container.querySelectorAll('.settings-difficulty').forEach(btn => {
      btn.addEventListener('click', () => {
        this.settings.difficulty = btn.dataset.difficulty;
        this._saveSettings();
        this._applySettings();
        this._rerender();
      });
    });

    this.container.querySelectorAll('.settings-toggle').forEach(btn => {
      btn.addEventListener('click', () => {
        const key = btn.dataset.key;
        this.settings[key] = !this.settings[key];
        this._saveSettings();
        this._applySettings();
        this._rerender();
      });
    });

    const slider = $('[data-action="camera-speed"]');
    if (slider) {
      slider.addEventListener('input', () => {
        this.settings.cameraSpeed = parseFloat(slider.value);
        $('[data-label="camera-speed-val"]').textContent = this.settings.cameraSpeed + 'x';
        this._saveSettings();
        this._applySettings();
      });
    }

    $('[data-action="reset-progress"]').addEventListener('click', () => {
      if (confirm('Reset ALL game progress? This cannot be undone.')) {
        localStorage.removeItem('k8sgames_progress');
        localStorage.removeItem('k8sgames_investigation');
        window.location.reload();
      }
    });

    $('[data-action="export"]').addEventListener('click', () => {
      const data = {
        progress: localStorage.getItem('k8sgames_progress'),
        settings: localStorage.getItem(STORAGE_KEY),
        investigation: localStorage.getItem('k8sgames_investigation'),
        exportedAt: new Date().toISOString(),
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `k8sgames-save-${new Date().toISOString().slice(0,10)}.json`;
      a.click();
      URL.revokeObjectURL(url);
    });
  }

  _rerender() {
    const scrollTop = this.container.querySelector('.overflow-y-auto')?.scrollTop || 0;
    this.container.innerHTML = this._buildHTML();
    this._bindEvents();
    const scroller = this.container.querySelector('.overflow-y-auto');
    if (scroller) scroller.scrollTop = scrollTop;
  }

  _applySettings() {
    const engine = window.game?.engine;
    const gameEngine = window.game?.gameEngine;

    if (gameEngine?.setDifficulty) {
      gameEngine.setDifficulty(this.settings.difficulty);
    }
    if (engine) {
      engine.emit('settings:changed', this.settings);
    }

    const minimap = document.getElementById('minimap');
    if (minimap) minimap.style.display = this.settings.showMinimap ? '' : 'none';
  }

  show() {
    this.visible = true;
    this.container.classList.remove('hidden');
    this._rerender();
  }

  hide() {
    this.visible = false;
    this.container.classList.add('hidden');
  }

  toggle() {
    if (this.visible) this.hide();
    else this.show();
  }

  getSettings() {
    return { ...this.settings };
  }

  destroy() {
    this.container?.remove();
  }
}

import * as THREE from 'three';

const POOL_SIZE = 2048;
const PARTICLE_BASE_SIZE = 3.0;
const PARTICLE_MIN_SPEED = 1.5;
const PARTICLE_MAX_SPEED = 4.0;
const SPAWN_INTERVAL = 0.05;
const TRAIL_LENGTH = 3;
const FADE_IN_DURATION = 0.15;
const FADE_OUT_START = 0.85;

const TRAFFIC_COLORS = {
    healthy: new THREE.Color(0x3fb950),
    error:   new THREE.Color(0xf85149),
    slow:    new THREE.Color(0xd29922),
    default: new THREE.Color(0x58a6ff)
};

const vertexShader = `
    attribute float size;
    attribute float alpha;
    attribute vec3 color;
    varying float vAlpha;
    varying vec3 vColor;

    void main() {
        vAlpha = alpha;
        vColor = color;
        vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = size * (200.0 / -mvPosition.z);
        gl_PointSize = max(gl_PointSize, 1.0);
        gl_Position = projectionMatrix * mvPosition;
    }
`;

const fragmentShader = `
    varying float vAlpha;
    varying vec3 vColor;

    void main() {
        vec2 center = gl_PointCoord - vec2(0.5);
        float dist = length(center);
        if (dist > 0.5) discard;

        float intensity = 1.0 - smoothstep(0.0, 0.5, dist);
        float glow = exp(-dist * 4.0) * 0.6;
        float finalAlpha = (intensity + glow) * vAlpha;

        gl_FragColor = vec4(vColor, finalAlpha);
    }
`;

class Particle {
    constructor() {
        this.active = false;
        this.routeId = null;
        this.progress = 0;
        this.speed = 0;
        this.color = new THREE.Color();
        this.alpha = 0;
        this.size = PARTICLE_BASE_SIZE;
        this.trailIndex = 0;
    }

    reset() {
        this.active = false;
        this.routeId = null;
        this.progress = 0;
        this.speed = 0;
        this.alpha = 0;
        this.trailIndex = 0;
    }
}

export class ParticleTrafficSystem {
    constructor(scene) {
        this.scene = scene;
        this.routes = new Map();
        this.particles = [];
        this.activeCount = 0;

        for (let i = 0; i < POOL_SIZE; i++) {
            this.particles.push(new Particle());
        }

        this._initGeometry();
        this._initMaterial();
        this._initPoints();

        this.spawnTimers = new Map();
    }

    _initGeometry() {
        this.geometry = new THREE.BufferGeometry();
        this.positions = new Float32Array(POOL_SIZE * 3);
        this.colors = new Float32Array(POOL_SIZE * 3);
        this.sizes = new Float32Array(POOL_SIZE);
        this.alphas = new Float32Array(POOL_SIZE);

        this.geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
        this.geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
        this.geometry.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1));
        this.geometry.setAttribute('alpha', new THREE.BufferAttribute(this.alphas, 1));

        for (let i = 0; i < POOL_SIZE; i++) {
            this.positions[i * 3] = 0;
            this.positions[i * 3 + 1] = -1000;
            this.positions[i * 3 + 2] = 0;
            this.sizes[i] = 0;
            this.alphas[i] = 0;
        }
    }

    _initMaterial() {
        this.material = new THREE.ShaderMaterial({
            vertexShader,
            fragmentShader,
            transparent: true,
            depthWrite: false,
            blending: THREE.AdditiveBlending
        });
    }

    _initPoints() {
        this.pointCloud = new THREE.Points(this.geometry, this.material);
        this.pointCloud.frustumCulled = false;
        this.scene.add(this.pointCloud);
    }

    addRoute(route) {
        if (this.routes.has(route.id)) return;

        const curve = this._buildCurve(route);
        if (!curve) return;

        this.routes.set(route.id, {
            id: route.id,
            curve,
            sourceId: route.sourceId,
            targetId: route.targetId,
            trafficType: route.trafficType || 'default',
            requestRate: route.requestRate || 1,
            color: TRAFFIC_COLORS[route.trafficType] || TRAFFIC_COLORS.default,
            active: true
        });

        this.spawnTimers.set(route.id, 0);
    }

    removeRoute(routeId) {
        this.routes.delete(routeId);
        this.spawnTimers.delete(routeId);

        for (const particle of this.particles) {
            if (particle.active && particle.routeId === routeId) {
                this._deactivateParticle(particle);
            }
        }
    }

    updateRoute(routeId, updates) {
        const route = this.routes.get(routeId);
        if (!route) return;

        if (updates.requestRate !== undefined) route.requestRate = updates.requestRate;
        if (updates.trafficType !== undefined) {
            route.trafficType = updates.trafficType;
            route.color = TRAFFIC_COLORS[updates.trafficType] || TRAFFIC_COLORS.default;
        }
        if (updates.sourcePos || updates.targetPos) {
            route.curve = this._buildCurve({
                sourcePos: updates.sourcePos || route.curve.v0,
                targetPos: updates.targetPos || route.curve.v2,
                ...route
            });
        }
    }

    _toVector3(pos) {
        if (pos instanceof THREE.Vector3) return pos;
        return new THREE.Vector3(pos.x, pos.y, pos.z);
    }

    _buildCurve(route) {
        if (!route.sourcePos || !route.targetPos) {
            return route.curve || null;
        }

        const start = this._toVector3(route.sourcePos);
        const end = this._toVector3(route.targetPos);

        const mid = new THREE.Vector3().lerpVectors(start, end, 0.5);
        const dist = start.distanceTo(end);
        mid.y += Math.min(dist * 0.25, 2.5);

        return new THREE.QuadraticBezierCurve3(start, mid, end);
    }

    _acquireParticle() {
        for (let i = 0; i < POOL_SIZE; i++) {
            if (!this.particles[i].active) {
                return { particle: this.particles[i], index: i };
            }
        }
        return null;
    }

    _deactivateParticle(particle) {
        const idx = this.particles.indexOf(particle);
        if (idx === -1) return;

        particle.reset();
        this.positions[idx * 3 + 1] = -1000;
        this.sizes[idx] = 0;
        this.alphas[idx] = 0;
        this.activeCount--;
    }

    _spawnParticle(route) {
        const slot = this._acquireParticle();
        if (!slot) return;

        const { particle, index } = slot;
        particle.active = true;
        particle.routeId = route.id;
        particle.progress = 0;
        particle.speed = PARTICLE_MIN_SPEED + Math.random() * (PARTICLE_MAX_SPEED - PARTICLE_MIN_SPEED);
        particle.color.copy(route.color);
        particle.alpha = 0;
        particle.size = PARTICLE_BASE_SIZE * (0.7 + Math.random() * 0.6);
        particle.trailIndex = 0;

        this.colors[index * 3] = route.color.r;
        this.colors[index * 3 + 1] = route.color.g;
        this.colors[index * 3 + 2] = route.color.b;

        this.activeCount++;
    }

    update(delta) {
        this._spawnNewParticles(delta);
        this._updateActiveParticles(delta);
        this._flushBuffers();
    }

    _spawnNewParticles(delta) {
        for (const [routeId, route] of this.routes) {
            if (!route.active) continue;

            let timer = this.spawnTimers.get(routeId) || 0;
            timer += delta;

            const interval = SPAWN_INTERVAL / Math.max(route.requestRate, 0.1);
            while (timer >= interval) {
                timer -= interval;
                this._spawnParticle(route);

                for (let t = 0; t < TRAIL_LENGTH - 1; t++) {
                    const trailSlot = this._acquireParticle();
                    if (!trailSlot) break;
                    const { particle: trail, index: trailIdx } = trailSlot;
                    trail.active = true;
                    trail.routeId = route.id;
                    trail.progress = -(t + 1) * 0.03;
                    trail.speed = PARTICLE_MIN_SPEED + Math.random() * (PARTICLE_MAX_SPEED - PARTICLE_MIN_SPEED);
                    trail.color.copy(route.color);
                    trail.alpha = 0;
                    trail.size = PARTICLE_BASE_SIZE * (0.5 - t * 0.12);
                    trail.trailIndex = t + 1;

                    this.colors[trailIdx * 3] = route.color.r * (1 - t * 0.2);
                    this.colors[trailIdx * 3 + 1] = route.color.g * (1 - t * 0.2);
                    this.colors[trailIdx * 3 + 2] = route.color.b * (1 - t * 0.2);
                }
            }

            this.spawnTimers.set(routeId, timer);
        }
    }

    _updateActiveParticles(delta) {
        const tmpVec = new THREE.Vector3();

        for (let i = 0; i < POOL_SIZE; i++) {
            const particle = this.particles[i];
            if (!particle.active) continue;

            const route = this.routes.get(particle.routeId);
            if (!route || !route.curve) {
                this._deactivateParticle(particle);
                continue;
            }

            particle.progress += particle.speed * delta / route.curve.getLength();

            if (particle.progress >= 1.0) {
                this._deactivateParticle(particle);
                continue;
            }

            const t = Math.max(0, Math.min(1, particle.progress));
            route.curve.getPoint(t, tmpVec);

            this.positions[i * 3] = tmpVec.x;
            this.positions[i * 3 + 1] = tmpVec.y;
            this.positions[i * 3 + 2] = tmpVec.z;

            let alpha = 1.0;
            if (t < FADE_IN_DURATION) {
                alpha = t / FADE_IN_DURATION;
            } else if (t > FADE_OUT_START) {
                alpha = 1.0 - (t - FADE_OUT_START) / (1.0 - FADE_OUT_START);
            }
            alpha *= (1.0 - particle.trailIndex * 0.3);
            particle.alpha = Math.max(0, alpha);

            this.alphas[i] = particle.alpha;
            this.sizes[i] = particle.size * (particle.alpha * 0.5 + 0.5);
        }
    }

    _flushBuffers() {
        this.geometry.attributes.position.needsUpdate = true;
        this.geometry.attributes.color.needsUpdate = true;
        this.geometry.attributes.size.needsUpdate = true;
        this.geometry.attributes.alpha.needsUpdate = true;
    }

    syncRoutes(routesMap) {
        const newIds = new Set();

        for (const [id, route] of routesMap) {
            newIds.add(id);
            if (this.routes.has(id)) {
                this.updateRoute(id, route);
            } else {
                this.addRoute(route);
            }
        }

        for (const id of [...this.routes.keys()]) {
            if (!newIds.has(id)) {
                this.removeRoute(id);
            }
        }
    }

    setRouteActive(routeId, active) {
        const route = this.routes.get(routeId);
        if (route) route.active = active;
    }

    getActiveParticleCount() {
        return this.activeCount;
    }

    getRouteCount() {
        return this.routes.size;
    }

    dispose() {
        for (const particle of this.particles) {
            particle.reset();
        }
        this.routes.clear();
        this.spawnTimers.clear();
        this.activeCount = 0;

        this.scene.remove(this.pointCloud);
        this.geometry.dispose();
        this.material.dispose();
    }
}

import { ResourceBase } from './ResourceBase.js';

export class ConfigMap extends ResourceBase {
  constructor(metadata = {}) {
    super('ConfigMap', metadata);
    this.data = metadata.data || {};
    this.binaryData = metadata.binaryData || {};
    this.immutable = metadata.immutable || false;
    this.mountedBy = [];
    this.envInjectedBy = [];
    this.setStatus('Active');
  }

  setData(key, value) {
    if (this.immutable) {
      this.addEvent('Warning', 'ImmutableViolation', `Cannot modify immutable ConfigMap`);
      return false;
    }
    this.data[key] = value;
    this.addEvent('Normal', 'Updated', `Key "${key}" updated`);
    return true;
  }

  deleteData(key) {
    if (this.immutable) {
      this.addEvent('Warning', 'ImmutableViolation', `Cannot modify immutable ConfigMap`);
      return false;
    }
    delete this.data[key];
    this.addEvent('Normal', 'Updated', `Key "${key}" deleted`);
    return true;
  }

  getData(key) {
    return this.data[key];
  }

  getKeys() {
    return Object.keys(this.data);
  }

  getSize() {
    return Object.entries(this.data).reduce((sum, [k, v]) => sum + k.length + v.length, 0);
  }

  addMountReference(podName) {
    if (!this.mountedBy.includes(podName)) {
      this.mountedBy.push(podName);
    }
  }

  removeMountReference(podName) {
    this.mountedBy = this.mountedBy.filter(n => n !== podName);
  }

  addEnvReference(podName) {
    if (!this.envInjectedBy.includes(podName)) {
      this.envInjectedBy.push(podName);
    }
  }

  removeEnvReference(podName) {
    this.envInjectedBy = this.envInjectedBy.filter(n => n !== podName);
  }


  getShape() { return 'scroll'; }
  getColor() { return '#92400e'; }

  toYAML() {
    return `apiVersion: v1
kind: ConfigMap
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
  labels:
${Object.entries(this.metadata.labels).map(([k, v]) => `    ${k}: "${v}"`).join('\n')}
${this.immutable ? 'immutable: true' : ''}
data:
${Object.entries(this.data).map(([k, v]) => {
  if (v.includes('\n')) return `  ${k}: |\n${v.split('\n').map(line => `    ${line}`).join('\n')}`;
  return `  ${k}: "${v}"`;
}).join('\n')}`;
  }

  toDescribe() {
    return `Name:         ${this.metadata.name}
Namespace:    ${this.metadata.namespace}
Labels:       ${Object.entries(this.metadata.labels).map(([k, v]) => `${k}=${v}`).join(', ')}
Annotations:  ${Object.entries(this.metadata.annotations).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>'}

Data
====
${Object.entries(this.data).map(([k, v]) => `${k}:
----
${v}
`).join('\n')}
BinaryData
====
${Object.keys(this.binaryData).length > 0 ? Object.entries(this.binaryData).map(([k, v]) => `${k}: ${v.length} bytes`).join('\n') : '<none>'}

Mounted By:    ${this.mountedBy.join(', ') || '<none>'}
Env Injected:  ${this.envInjectedBy.join(', ') || '<none>'}
Events:
${this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`).join('\n')}`;
  }
}

export class Secret extends ResourceBase {
  constructor(metadata = {}) {
    super('Secret', metadata);
    this.type = metadata.secretType || 'Opaque';
    this.data = {};
    this.stringData = metadata.stringData || {};
    this.immutable = metadata.immutable || false;
    this.mountedBy = [];
    this.envInjectedBy = [];

    if (metadata.data) {
      for (const [k, v] of Object.entries(metadata.data)) {
        this.data[k] = v;
      }
    } else if (metadata.stringData) {
      for (const [k, v] of Object.entries(metadata.stringData)) {
        this.data[k] = btoa(v);
      }
    }

    if (this.type === 'kubernetes.io/tls' && !this.data['tls.crt']) {
      this.data['tls.crt'] = btoa('-----BEGIN CERTIFICATE-----\nMIIBxTCCAW...\n-----END CERTIFICATE-----');
      this.data['tls.key'] = btoa('-----BEGIN PRIVATE KEY-----\nMIIEvgIBAD...\n-----END PRIVATE KEY-----');
    }

    if (this.type === 'kubernetes.io/dockerconfigjson' && !this.data['.dockerconfigjson']) {
      const dockerConfig = {
        auths: {
          'registry.example.com': {
            username: 'user',
            password: '***',
            auth: btoa('user:***'),
          },
        },
      };
      this.data['.dockerconfigjson'] = btoa(JSON.stringify(dockerConfig));
    }

    this.setStatus('Active');
  }

  setData(key, value, encode = true) {
    if (this.immutable) {
      this.addEvent('Warning', 'ImmutableViolation', `Cannot modify immutable Secret`);
      return false;
    }
    this.data[key] = encode ? btoa(value) : value;
    this.addEvent('Normal', 'Updated', `Key "${key}" updated`);
    return true;
  }

  getData(key, decode = true) {
    const val = this.data[key];
    if (!val) return undefined;
    return decode ? atob(val) : val;
  }

  deleteData(key) {
    if (this.immutable) return false;
    delete this.data[key];
    return true;
  }

  getKeys() {
    return Object.keys(this.data);
  }

  getSize() {
    return Object.values(this.data).reduce((sum, v) => sum + v.length, 0);
  }

  addMountReference(podName) {
    if (!this.mountedBy.includes(podName)) this.mountedBy.push(podName);
  }

  removeMountReference(podName) {
    this.mountedBy = this.mountedBy.filter(n => n !== podName);
  }

  addEnvReference(podName) {
    if (!this.envInjectedBy.includes(podName)) this.envInjectedBy.push(podName);
  }

  removeEnvReference(podName) {
    this.envInjectedBy = this.envInjectedBy.filter(n => n !== podName);
  }


  getShape() { return 'lock'; }
  getColor() { return '#991b1b'; }

  toYAML() {
    return `apiVersion: v1
kind: Secret
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
  labels:
${Object.entries(this.metadata.labels).map(([k, v]) => `    ${k}: "${v}"`).join('\n')}
type: ${this.type}
${this.immutable ? 'immutable: true' : ''}
data:
${Object.entries(this.data).map(([k, v]) => `  ${k}: ${v}`).join('\n')}`;
  }

  toDescribe() {
    return `Name:         ${this.metadata.name}
Namespace:    ${this.metadata.namespace}
Labels:       ${Object.entries(this.metadata.labels).map(([k, v]) => `${k}=${v}`).join(', ')}
Annotations:  ${Object.entries(this.metadata.annotations).map(([k, v]) => `${k}=${v}`).join(', ') || '<none>'}

Type:  ${this.type}

Data
====
${Object.entries(this.data).map(([k, v]) => `${k}:  ${atob(v).length} bytes`).join('\n')}

Mounted By:    ${this.mountedBy.join(', ') || '<none>'}
Env Injected:  ${this.envInjectedBy.join(', ') || '<none>'}
Events:
${this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`).join('\n')}`;
  }
}

const CHART_COLORS = {
  cpu: { line: '#60a5fa', fill: 'rgba(96, 165, 250, 0.1)' },
  memory: { line: '#c084fc', fill: 'rgba(192, 132, 252, 0.1)' },
  network: { line: '#34d399', fill: 'rgba(52, 211, 153, 0.1)' },
  pods: { line: '#fbbf24', fill: 'rgba(251, 191, 36, 0.1)' },
};

const WINDOW_SIZE = 60;

export class MetricsDashboard {
  constructor() {
    this.container = null;
    this.visible = false;
    this.canvases = {};
    this.contexts = {};
    this.data = {
      cpu: [],
      memory: [],
      network: [],
      pods: [],
    };
    this.selectedResource = null;
    this._animFrameId = null;
    this._boundKeydown = this._onKeydown.bind(this);
    this._boundTick = this._onTick.bind(this);
    this._boundSelect = this._onResourceSelect.bind(this);
    this._boundResize = this._onResize.bind(this);
    this._boundDeselect = this._onResourceDeselect.bind(this);
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'metrics-dashboard';
    this.container.className = 'fixed bottom-0 left-0 right-0 z-30 transform translate-y-full transition-transform duration-300 ease-out';
    this.container.innerHTML = this._buildHTML();
    document.body.appendChild(this.container);
    this._initCanvases();
    this._bindEvents();
  }

  _buildHTML() {
    return `
      <div class="backdrop-blur-xl bg-white/5 border-t border-white/10 shadow-2xl" style="height: 240px;">
        <div class="flex items-center justify-between px-4 py-2 border-b border-white/5">
          <div class="flex items-center gap-3">
            <span class="text-white/40 text-xs font-mono">Metrics</span>
            <span id="metrics-scope" class="text-white/20 text-xs">Cluster-wide</span>
          </div>
          <div class="flex items-center gap-2">
            <span class="text-white/20 text-xs">Press M to toggle</span>
            <button id="metrics-close" class="p-1 text-white/30 hover:text-white/60 transition-colors">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
              </svg>
            </button>
          </div>
        </div>
        <div class="grid grid-cols-4 gap-3 p-3 h-[calc(100%-40px)]">
          <div class="relative">
            <div class="absolute top-0 left-0 text-[10px] text-white/30 z-10 px-1">CPU %</div>
            <div class="absolute top-0 right-0 text-[10px] font-mono z-10 px-1" id="metrics-cpu-val" style="color: ${CHART_COLORS.cpu.line}">0%</div>
            <canvas id="metrics-canvas-cpu" class="w-full h-full rounded-lg bg-white/5 border border-white/5"></canvas>
          </div>
          <div class="relative">
            <div class="absolute top-0 left-0 text-[10px] text-white/30 z-10 px-1">Memory %</div>
            <div class="absolute top-0 right-0 text-[10px] font-mono z-10 px-1" id="metrics-mem-val" style="color: ${CHART_COLORS.memory.line}">0%</div>
            <canvas id="metrics-canvas-memory" class="w-full h-full rounded-lg bg-white/5 border border-white/5"></canvas>
          </div>
          <div class="relative">
            <div class="absolute top-0 left-0 text-[10px] text-white/30 z-10 px-1">Network KB/s</div>
            <div class="absolute top-0 right-0 text-[10px] font-mono z-10 px-1" id="metrics-net-val" style="color: ${CHART_COLORS.network.line}">0</div>
            <canvas id="metrics-canvas-network" class="w-full h-full rounded-lg bg-white/5 border border-white/5"></canvas>
          </div>
          <div class="relative">
            <div class="absolute top-0 left-0 text-[10px] text-white/30 z-10 px-1">Pod Count</div>
            <div class="absolute top-0 right-0 text-[10px] font-mono z-10 px-1" id="metrics-pods-val" style="color: ${CHART_COLORS.pods.line}">0</div>
            <canvas id="metrics-canvas-pods" class="w-full h-full rounded-lg bg-white/5 border border-white/5"></canvas>
          </div>
        </div>
      </div>
    `;
  }

  _initCanvases() {
    for (const key of ['cpu', 'memory', 'network', 'pods']) {
      const canvas = document.getElementById(`metrics-canvas-${key}`);
      this.canvases[key] = canvas;
      this.contexts[key] = canvas.getContext('2d');
    }
    this._resizeCanvases();
  }

  _resizeCanvases() {
    for (const key of Object.keys(this.canvases)) {
      const canvas = this.canvases[key];
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * window.devicePixelRatio;
      canvas.height = rect.height * window.devicePixelRatio;
      const dpr = window.devicePixelRatio;
      this.contexts[key].setTransform(dpr, 0, 0, dpr, 0, 0);
    }
  }

  _bindEvents() {
    document.addEventListener('keydown', this._boundKeydown);
    document.getElementById('metrics-close').addEventListener('click', () => this.hide());
    window.addEventListener('resize', this._boundResize);

    const engine = window.game?.engine;
    if (engine) {
      engine.on('tick', this._boundTick);
      engine.on('resource:selected', this._boundSelect);
      engine.on('resource:deselected', this._boundDeselect);
    }
  }

  _onResourceDeselect() {
    this.selectedResource = null;
    document.getElementById('metrics-scope').textContent = 'Cluster-wide';
  }

  _onKeydown(e) {
    if (e.key === 'm' || e.key === 'M') {
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      this.toggle();
    }
  }

  _onTick(state) {
    const cluster = window.game?.cluster;
    const stats = cluster?.getClusterStats?.() || {};

    const nodes = cluster?.getResourcesByKind?.('Node') || [];
    let totalCpuUsed = 0, totalCpuCap = 0, totalMemUsed = 0, totalMemCap = 0;
    for (const n of nodes) {
      const cpuCap = parseInt(n.spec?.cpu || n.status?.capacity?.cpu || '4') * 1000;
      const memCapStr = n.spec?.memory || n.status?.capacity?.memory || '8Gi';
      const memCap = parseInt(memCapStr) * (memCapStr.includes('Gi') ? 1024 : 1);
      totalCpuUsed += n.status?.usage?.cpu ?? n.cpuUsage ?? 0;
      totalCpuCap += cpuCap;
      totalMemUsed += n.status?.usage?.memory ?? n.memoryUsage ?? 0;
      totalMemCap += memCap;
    }

    const cpu = totalCpuCap > 0 ? (totalCpuUsed / totalCpuCap) * 100 : 0;
    const memory = totalMemCap > 0 ? (totalMemUsed / totalMemCap) * 100 : 0;
    const pods = cluster?.getResourcesByKind?.('Pod')?.length ?? 0;
    const runningPods = cluster?.getResourcesByKind?.('Pod')?.filter(p => p.status?.phase === 'Running')?.length ?? 0;
    const network = runningPods * (2 + Math.sin(this.data.network.length * 0.1) * 1.5);

    if (this.selectedResource) {
      const r = this.selectedResource;
      this.data.cpu.push(r.cpuUsage ?? r.status?.cpuUsage ?? cpu * (0.3 + Math.random() * 0.4));
      this.data.memory.push(r.memoryUsage ?? r.status?.memoryUsage ?? memory * (0.3 + Math.random() * 0.4));
      this.data.network.push(network * (0.1 + Math.random() * 0.3));
      this.data.pods.push(pods);
    } else {
      this.data.cpu.push(cpu);
      this.data.memory.push(memory);
      this.data.network.push(network);
      this.data.pods.push(pods);
    }

    for (const key of Object.keys(this.data)) {
      while (this.data[key].length > WINDOW_SIZE) this.data[key].shift();
    }

    const lastCpu = Math.round(this.data.cpu[this.data.cpu.length - 1] || 0);
    const lastMem = Math.round(this.data.memory[this.data.memory.length - 1] || 0);
    const lastNet = Math.round(this.data.network[this.data.network.length - 1] || 0);
    const el = (id) => document.getElementById(id);
    if (el('metrics-cpu-val')) el('metrics-cpu-val').textContent = lastCpu + '%';
    if (el('metrics-mem-val')) el('metrics-mem-val').textContent = lastMem + '%';
    if (el('metrics-net-val')) el('metrics-net-val').textContent = lastNet + '';
    if (el('metrics-pods-val')) el('metrics-pods-val').textContent = pods + '';

    if (this.visible) this._draw();
  }

  _onResourceSelect(data) {
    this.selectedResource = window.game?.cluster?.getResource(data.uid) || null;
    const name = this.selectedResource?.metadata?.name || 'Unknown';
    document.getElementById('metrics-scope').textContent = this.selectedResource ? `Resource: ${name}` : 'Cluster-wide';
  }

  _onResize() {
    if (this.visible) {
      this._resizeCanvases();
      this._draw();
    }
  }

  _draw() {
    this._drawChart('cpu', this.data.cpu, CHART_COLORS.cpu, '%', 100);
    this._drawChart('memory', this.data.memory, CHART_COLORS.memory, '%', 100);
    this._drawChart('network', this.data.network, CHART_COLORS.network, '', null);
    this._drawChart('pods', this.data.pods, CHART_COLORS.pods, '', null);

    const lastCpu = this.data.cpu[this.data.cpu.length - 1] ?? 0;
    const lastMem = this.data.memory[this.data.memory.length - 1] ?? 0;
    const lastNet = this.data.network[this.data.network.length - 1] ?? 0;
    const lastPods = this.data.pods[this.data.pods.length - 1] ?? 0;

    document.getElementById('metrics-cpu-val').textContent = `${Math.round(lastCpu)}%`;
    document.getElementById('metrics-mem-val').textContent = `${Math.round(lastMem)}%`;
    document.getElementById('metrics-net-val').textContent = `${Math.round(lastNet)}`;
    document.getElementById('metrics-pods-val').textContent = `${Math.round(lastPods)}`;
  }

  _drawChart(key, data, colors, suffix, fixedMax) {
    const ctx = this.contexts[key];
    const canvas = this.canvases[key];
    const w = canvas.width / window.devicePixelRatio;
    const h = canvas.height / window.devicePixelRatio;

    ctx.clearRect(0, 0, w, h);

    if (data.length < 2) return;

    const padding = { top: 18, right: 4, bottom: 4, left: 4 };
    const chartW = w - padding.left - padding.right;
    const chartH = h - padding.top - padding.bottom;

    let maxVal = fixedMax;
    if (maxVal === null) {
      maxVal = Math.max(...data) * 1.2;
      if (maxVal < 1) maxVal = 1;
      maxVal = this._niceMax(maxVal);
    }

    const gridLines = 4;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
    ctx.lineWidth = 0.5;
    for (let i = 1; i < gridLines; i++) {
      const gy = padding.top + (chartH / gridLines) * i;
      ctx.beginPath();
      ctx.moveTo(padding.left, gy);
      ctx.lineTo(w - padding.right, gy);
      ctx.stroke();
    }

    const points = data.map((val, i) => ({
      x: padding.left + (i / (WINDOW_SIZE - 1)) * chartW,
      y: padding.top + chartH - (val / maxVal) * chartH,
    }));

    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i++) {
      const prev = points[i - 1];
      const curr = points[i];
      const cpx = (prev.x + curr.x) / 2;
      ctx.bezierCurveTo(cpx, prev.y, cpx, curr.y, curr.x, curr.y);
    }
    ctx.strokeStyle = colors.line;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    const lastPoint = points[points.length - 1];
    ctx.lineTo(lastPoint.x, padding.top + chartH);
    ctx.lineTo(points[0].x, padding.top + chartH);
    ctx.closePath();

    const gradient = ctx.createLinearGradient(0, padding.top, 0, padding.top + chartH);
    gradient.addColorStop(0, colors.fill);
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(lastPoint.x, lastPoint.y, 3, 0, Math.PI * 2);
    ctx.fillStyle = colors.line;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(lastPoint.x, lastPoint.y, 5, 0, Math.PI * 2);
    ctx.strokeStyle = colors.line;
    ctx.lineWidth = 0.5;
    ctx.globalAlpha = 0.3;
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  _niceMax(val) {
    const magnitude = Math.pow(10, Math.floor(Math.log10(val)));
    const normalized = val / magnitude;
    if (normalized <= 1) return magnitude;
    if (normalized <= 2) return 2 * magnitude;
    if (normalized <= 5) return 5 * magnitude;
    return 10 * magnitude;
  }

  show() {
    this.visible = true;
    this.container.classList.remove('translate-y-full');
    this.container.classList.add('translate-y-0');
    this._resizeCanvases();
    this._draw();
  }

  hide() {
    this.visible = false;
    this.container.classList.remove('translate-y-0');
    this.container.classList.add('translate-y-full');
  }

  toggle() {
    if (this.visible) this.hide();
    else this.show();
  }

  destroy() {
    document.removeEventListener('keydown', this._boundKeydown);
    window.removeEventListener('resize', this._boundResize);
    const engine = window.game?.engine;
    if (engine) {
      engine.off?.('tick', this._boundTick);
      engine.off?.('resource:selected', this._boundSelect);
      engine.off?.('resource:deselected', this._boundDeselect);
    }
    if (this._animFrameId) cancelAnimationFrame(this._animFrameId);
    this.container?.remove();
  }
}

const NAMESPACE_COLORS = {
  default: '#60a5fa',
  'kube-system': '#34d399',
  'kube-public': '#a78bfa',
  monitoring: '#fbbf24',
  ingress: '#f87171',
  logging: '#fb923c',
};

const KIND_SIZES = {
  Node: 5,
  Deployment: 3.5,
  Pod: 2,
  Service: 3,
  ConfigMap: 1.5,
  Secret: 1.5,
  Ingress: 3,
  StatefulSet: 3.5,
  DaemonSet: 3.5,
};

export class Minimap {
  constructor() {
    this.container = null;
    this.canvas = null;
    this.ctx = null;
    this.visible = true;
    this.viewport = { x: 0, y: 0, w: 1, h: 1 };
    this.resourcePositions = new Map();
    this.incidentResources = new Set();
    this.pulsePhase = 0;
    this._animFrameId = null;
    this._boundTick = this._onTick.bind(this);
    this._boundIncident = this._onIncident.bind(this);
    this._boundResolve = this._onIncidentResolved.bind(this);
    this._boundViewport = this._onViewportChange.bind(this);
    this._dragging = false;
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'minimap';
    this.container.className = 'fixed bottom-4 right-4 z-20';
    this.container.innerHTML = this._buildHTML();
    document.body.appendChild(this.container);

    this.canvas = document.getElementById('minimap-canvas');
    this.ctx = this.canvas.getContext('2d');
    this._setupCanvas();
    this._bindEvents();
    this._startAnimation();
  }

  _buildHTML() {
    return `
      <div class="backdrop-blur-xl bg-white/5 border border-white/10 rounded-lg overflow-hidden shadow-xl" style="width: 180px; height: 140px;">
        <div class="flex items-center justify-between px-2 py-1 border-b border-white/5">
          <span class="text-white/30 text-[10px] font-mono">Cluster Map</span>
          <button id="minimap-toggle" class="text-white/20 hover:text-white/40 text-[10px] transition-colors">-</button>
        </div>
        <canvas id="minimap-canvas" style="width: 180px; height: 118px;"></canvas>
      </div>
    `;
  }

  _setupCanvas() {
    const dpr = window.devicePixelRatio;
    this.canvas.width = 180 * dpr;
    this.canvas.height = 118 * dpr;
    this.ctx.scale(dpr, dpr);
  }

  _bindEvents() {
    this.canvas.addEventListener('mousedown', (e) => this._onMouseDown(e));
    this.canvas.addEventListener('mousemove', (e) => this._onMouseMove(e));
    this.canvas.addEventListener('mouseup', () => this._onMouseUp());
    this.canvas.addEventListener('mouseleave', () => this._onMouseUp());

    document.getElementById('minimap-toggle').addEventListener('click', () => {
      const body = this.canvas;
      if (body.style.display === 'none') {
        body.style.display = '';
        this.container.querySelector('div').style.height = '';
        document.getElementById('minimap-toggle').textContent = '-';
      } else {
        body.style.display = 'none';
        document.getElementById('minimap-toggle').textContent = '+';
      }
    });

    const engine = window.game?.engine;
    if (engine) {
      engine.on('tick', this._boundTick);
      engine.on('incident:created', this._boundIncident);
      engine.on('incident:resolved', this._boundResolve);
      engine.on('viewport:change', this._boundViewport);
    }
  }

  _onMouseDown(e) {
    this._dragging = true;
    this._navigateTo(e);
  }

  _onMouseMove(e) {
    if (this._dragging) this._navigateTo(e);
  }

  _onMouseUp() {
    this._dragging = false;
  }

  _navigateTo(e) {
    const rect = this.canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    window.game?.engine.emit('minimap:navigate', { x, y });
    window.game?.renderer?.focusResource?.(null, x, y);
  }

  _onTick() {
    this._updatePositions();
  }

  _onIncident(data) {
    if (data.uid) this.incidentResources.add(data.uid);
  }

  _onIncidentResolved(data) {
    if (data.uid) this.incidentResources.delete(data.uid);
  }

  _onViewportChange(data) {
    this.viewport = { x: data.x ?? 0, y: data.y ?? 0, w: data.w ?? 1, h: data.h ?? 1 };
  }

  _updatePositions() {
    const cluster = window.game?.cluster;
    if (!cluster) return;

    const all = cluster.getAllResources?.() || [];
    this.resourcePositions.clear();

    for (const r of all) {
      const uid = r.metadata?.uid;
      if (!uid) continue;

      if (r._position) {
        this.resourcePositions.set(uid, {
          x: r._position.x,
          y: r._position.y,
          kind: r.kind,
          namespace: r.metadata?.namespace || 'default',
          status: r.status?.phase || 'Active',
        });
      } else {
        const hash = this._hashString(uid);
        this.resourcePositions.set(uid, {
          x: (hash % 1000) / 1000,
          y: ((hash >> 10) % 1000) / 1000,
          kind: r.kind,
          namespace: r.metadata?.namespace || 'default',
          status: r.status?.phase || 'Active',
        });
      }
    }
  }

  _startAnimation() {
    const animate = () => {
      this.pulsePhase += 0.05;
      this._draw();
      this._animFrameId = requestAnimationFrame(animate);
    };
    this._animFrameId = requestAnimationFrame(animate);
  }

  _draw() {
    const w = 180;
    const h = 118;
    const ctx = this.ctx;

    ctx.clearRect(0, 0, w, h);

    ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
    ctx.fillRect(0, 0, w, h);

    const padding = 8;
    const drawW = w - padding * 2;
    const drawH = h - padding * 2;

    for (const [uid, pos] of this.resourcePositions) {
      const x = padding + pos.x * drawW;
      const y = padding + pos.y * drawH;
      const size = KIND_SIZES[pos.kind] || 2;
      const color = NAMESPACE_COLORS[pos.namespace] || '#60a5fa';

      const isIncident = this.incidentResources.has(uid);

      if (isIncident) {
        const pulse = Math.sin(this.pulsePhase * 3) * 0.5 + 0.5;
        const pulseRadius = size + 3 + pulse * 4;
        ctx.beginPath();
        ctx.arc(x, y, pulseRadius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(248, 113, 113, ${0.15 + pulse * 0.15})`;
        ctx.fill();
      }

      ctx.beginPath();
      ctx.arc(x, y, size, 0, Math.PI * 2);

      if (pos.status === 'Failed' || pos.status === 'CrashLoopBackOff') {
        ctx.fillStyle = '#f87171';
      } else if (pos.status === 'Pending') {
        ctx.fillStyle = '#fbbf24';
      } else {
        ctx.fillStyle = color;
      }

      ctx.globalAlpha = isIncident ? 1 : 0.7;
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    ctx.strokeStyle = 'rgba(96, 165, 250, 0.4)';
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 2]);
    ctx.strokeRect(
      padding + this.viewport.x * drawW,
      padding + this.viewport.y * drawH,
      this.viewport.w * drawW,
      this.viewport.h * drawH
    );
    ctx.setLineDash([]);

    ctx.fillStyle = 'rgba(96, 165, 250, 0.05)';
    ctx.fillRect(
      padding + this.viewport.x * drawW,
      padding + this.viewport.y * drawH,
      this.viewport.w * drawW,
      this.viewport.h * drawH
    );
  }

  _hashString(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash |= 0;
    }
    return Math.abs(hash);
  }

  show() {
    this.visible = true;
    this.container.classList.remove('hidden');
  }

  hide() {
    this.visible = false;
    this.container.classList.add('hidden');
  }

  toggle() {
    if (this.visible) this.hide();
    else this.show();
  }

  destroy() {
    const engine = window.game?.engine;
    if (engine) {
      engine.off?.('tick', this._boundTick);
      engine.off?.('incident:created', this._boundIncident);
      engine.off?.('incident:resolved', this._boundResolve);
      engine.off?.('viewport:change', this._boundViewport);
    }
    if (this._animFrameId) cancelAnimationFrame(this._animFrameId);
    this.container?.remove();
  }
}

let uidCounter = 0;

function generateUID() {
  uidCounter++;
  const timestamp = Date.now().toString(36);
  const random = Math.random().toString(36).substring(2, 10);
  return `${timestamp}-${random}-${uidCounter.toString(36).padStart(4, '0')}`;
}

export class ResourceBase {
  constructor(kind, apiVersionOrMeta, name, namespace = 'default') {
    this.kind = kind;
    if (typeof apiVersionOrMeta === 'object' && apiVersionOrMeta !== null) {
      const meta = apiVersionOrMeta;
      this.apiVersion = meta.apiVersion || 'v1';
      this.metadata = {
        name: meta.name || 'unnamed',
        namespace: meta.namespace ?? 'default',
        uid: generateUID(),
        labels: meta.labels ? { ...meta.labels } : {},
        annotations: meta.annotations ? { ...meta.annotations } : {},
        creationTimestamp: new Date().toISOString(),
        deletionTimestamp: null,
        generation: 1,
        resourceVersion: '1',
        ownerReferences: meta.ownerReferences ? [...meta.ownerReferences] : [],
        finalizers: meta.finalizers ? [...meta.finalizers] : [],
      };
    } else {
      this.apiVersion = apiVersionOrMeta || 'v1';
      this.metadata = {
        name: name || 'unnamed',
        namespace,
        uid: generateUID(),
        labels: {},
        annotations: {},
        creationTimestamp: new Date().toISOString(),
        deletionTimestamp: null,
        generation: 1,
        resourceVersion: '1',
        ownerReferences: [],
        finalizers: [],
      };
    }
    this.spec = {};
    this.status = {
      phase: 'Pending',
      conditions: [],
      observedGeneration: 0,
    };
    this._events = [];
    this._maxEvents = 50;
    this._deleted = false;
    this._listeners = new Map();
  }

  get name() {
    return this.metadata.name;
  }

  get namespace() {
    return this.metadata.namespace;
  }

  get uid() {
    return this.metadata.uid;
  }

  get labels() {
    return this.metadata.labels;
  }

  get annotations() {
    return this.metadata.annotations;
  }

  get age() {
    const created = new Date(this.metadata.creationTimestamp).getTime();
    return Date.now() - created;
  }

  get ageFormatted() {
    const ms = this.age;
    const seconds = Math.floor(ms / 1000);
    if (seconds < 60) return `${seconds}s`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h`;
    const days = Math.floor(hours / 24);
    return `${days}d`;
  }

  get isDeleting() {
    return this.metadata.deletionTimestamp !== null;
  }

  get fullyQualifiedName() {
    return `${this.metadata.namespace}/${this.kind}/${this.metadata.name}`;
  }

  setLabel(key, value) {
    this.metadata.labels[key] = value;
    this._bumpResourceVersion();
    return this;
  }

  removeLabel(key) {
    delete this.metadata.labels[key];
    this._bumpResourceVersion();
    return this;
  }

  setAnnotation(key, value) {
    this.metadata.annotations[key] = value;
    this._bumpResourceVersion();
    return this;
  }

  removeAnnotation(key) {
    delete this.metadata.annotations[key];
    this._bumpResourceVersion();
    return this;
  }

  matchesSelector(selector) {
    if (!selector || Object.keys(selector).length === 0) return true;
    for (const [key, value] of Object.entries(selector)) {
      if (this.metadata.labels[key] !== value) return false;
    }
    return true;
  }

  matchesFieldSelector(field, value) {
    const parts = field.split('.');
    let current = this;
    for (const part of parts) {
      if (current == null || typeof current !== 'object') return false;
      current = current[part];
    }
    return String(current) === String(value);
  }

  addOwnerReference(owner) {
    const ref = {
      apiVersion: owner.apiVersion,
      kind: owner.kind,
      name: owner.metadata.name,
      uid: owner.metadata.uid,
      controller: true,
      blockOwnerDeletion: true,
    };
    const existing = this.metadata.ownerReferences.findIndex(
      (r) => r.uid === ref.uid
    );
    if (existing >= 0) {
      this.metadata.ownerReferences[existing] = ref;
    } else {
      this.metadata.ownerReferences.push(ref);
    }
    this._bumpResourceVersion();
    return this;
  }

  removeOwnerReference(ownerUid) {
    this.metadata.ownerReferences = this.metadata.ownerReferences.filter(
      (r) => r.uid !== ownerUid
    );
    this._bumpResourceVersion();
    return this;
  }

  getControllerOwner() {
    return this.metadata.ownerReferences.find((r) => r.controller) || null;
  }

  addFinalizer(name) {
    if (!this.metadata.finalizers.includes(name)) {
      this.metadata.finalizers.push(name);
      this._bumpResourceVersion();
    }
    return this;
  }

  removeFinalizer(name) {
    this.metadata.finalizers = this.metadata.finalizers.filter(
      (f) => f !== name
    );
    this._bumpResourceVersion();
    return this;
  }

  markForDeletion() {
    if (!this.metadata.deletionTimestamp) {
      this.metadata.deletionTimestamp = new Date().toISOString();
      this._bumpResourceVersion();
      this.recordEvent('Normal', 'Killing', 'Resource marked for deletion');
    }
    return this;
  }

  canBeRemoved() {
    return (
      this.metadata.deletionTimestamp !== null &&
      this.metadata.finalizers.length === 0
    );
  }

  setCondition(type, status, reason = '', message = '') {
    const now = new Date().toISOString();
    const existing = this.status.conditions.findIndex((c) => c.type === type);
    const condition = {
      type,
      status: String(status),
      reason,
      message,
      lastTransitionTime: now,
      lastHeartbeatTime: now,
    };
    if (existing >= 0) {
      const prev = this.status.conditions[existing];
      if (prev.status === condition.status) {
        condition.lastTransitionTime = prev.lastTransitionTime;
      }
      this.status.conditions[existing] = condition;
    } else {
      this.status.conditions.push(condition);
    }
    this._bumpResourceVersion();
    return this;
  }

  getCondition(type) {
    return this.status.conditions.find((c) => c.type === type) || null;
  }

  isConditionTrue(type) {
    const condition = this.getCondition(type);
    return condition ? condition.status === 'True' : false;
  }

  setPhase(phase) {
    if (this.status.phase !== phase) {
      const oldPhase = this.status.phase;
      this.status.phase = phase;
      this._bumpResourceVersion();
      this.recordEvent(
        'Normal',
        'PhaseChange',
        `Phase changed from ${oldPhase} to ${phase}`
      );
    }
    return this;
  }

  setStatus(status) {
    return this.setPhase(status);
  }

  updateSpec(partialSpec) {
    Object.assign(this.spec, partialSpec);
    this.metadata.generation++;
    this._bumpResourceVersion();
    return this;
  }

  get events() {
    return this._events;
  }

  tick(deltaTime) {}

  addEvent(type, reason, message) {
    return this.recordEvent(type, reason, message);
  }

  recordEvent(type, reason, message) {
    const event = {
      type,
      reason,
      message,
      timestamp: new Date().toISOString(),
      count: 1,
      source: this.kind,
      involvedObject: {
        kind: this.kind,
        name: this.metadata.name,
        namespace: this.metadata.namespace,
        uid: this.metadata.uid,
      },
    };
    if (this._events.length > 0) {
      const last = this._events[this._events.length - 1];
      if (last.reason === reason && last.message === message) {
        last.count++;
        last.timestamp = event.timestamp;
        return this;
      }
    }
    this._events.push(event);
    if (this._events.length > this._maxEvents) {
      this._events.shift();
    }
    return this;
  }

  getEvents(limit) {
    if (limit) {
      return this._events.slice(-limit);
    }
    return [...this._events];
  }

  getWarningEvents() {
    return this._events.filter((e) => e.type === 'Warning');
  }

  on(event, callback) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    this._listeners.get(event).push(callback);
    return this;
  }

  off(event, callback) {
    const list = this._listeners.get(event);
    if (list) {
      this._listeners.set(
        event,
        list.filter((cb) => cb !== callback)
      );
    }
    return this;
  }

  emit(event, data) {
    const list = this._listeners.get(event);
    if (list) {
      for (const cb of list) {
        cb(data);
      }
    }
  }

  _bumpResourceVersion() {
    this.metadata.resourceVersion = String(
      parseInt(this.metadata.resourceVersion, 10) + 1
    );
  }

  toJSON() {
    return {
      apiVersion: this.apiVersion,
      kind: this.kind,
      metadata: {
        ...this.metadata,
        ownerReferences: [...this.metadata.ownerReferences],
        finalizers: [...this.metadata.finalizers],
        labels: { ...this.metadata.labels },
        annotations: { ...this.metadata.annotations },
      },
      spec: JSON.parse(JSON.stringify(this.spec)),
      status: {
        ...this.status,
        conditions: this.status.conditions.map((c) => ({ ...c })),
      },
    };
  }

  toYAML(indent = 0) {
    const pad = (level) => '  '.repeat(level);
    const lines = [];

    const renderValue = (val, level) => {
      if (val === null || val === undefined) return 'null';
      if (typeof val === 'boolean') return String(val);
      if (typeof val === 'number') return String(val);
      if (typeof val === 'string') {
        if (val.includes('\n') || val.includes(':') || val.includes('#') || val.includes("'") || val === '') {
          return `"${val.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n')}"`;
        }
        return val;
      }
      return String(val);
    };

    const renderObject = (obj, level) => {
      if (obj === null || obj === undefined) {
        lines.push(`${pad(level)}null`);
        return;
      }
      if (Array.isArray(obj)) {
        if (obj.length === 0) {
          lines[lines.length - 1] += ' []';
          return;
        }
        for (const item of obj) {
          if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
            const entries = Object.entries(item);
            if (entries.length > 0) {
              const [firstKey, firstVal] = entries[0];
              if (typeof firstVal === 'object' && firstVal !== null) {
                lines.push(`${pad(level)}- ${firstKey}:`);
                renderObject(firstVal, level + 2);
              } else {
                lines.push(`${pad(level)}- ${firstKey}: ${renderValue(firstVal, level + 1)}`);
              }
              for (let i = 1; i < entries.length; i++) {
                const [k, v] = entries[i];
                if (typeof v === 'object' && v !== null) {
                  lines.push(`${pad(level + 1)}${k}:`);
                  renderObject(v, level + 2);
                } else {
                  lines.push(`${pad(level + 1)}${k}: ${renderValue(v, level + 1)}`);
                }
              }
            } else {
              lines.push(`${pad(level)}- {}`);
            }
          } else {
            lines.push(`${pad(level)}- ${renderValue(item, level)}`);
          }
        }
        return;
      }
      const entries = Object.entries(obj);
      if (entries.length === 0) {
        lines[lines.length - 1] += ' {}';
        return;
      }
      for (const [key, value] of entries) {
        if (value === undefined) continue;
        if (typeof value === 'object' && value !== null) {
          lines.push(`${pad(level)}${key}:`);
          renderObject(value, level + 1);
        } else {
          lines.push(`${pad(level)}${key}: ${renderValue(value, level)}`);
        }
      }
    };

    lines.push(`${pad(indent)}apiVersion: ${renderValue(this.apiVersion, indent)}`);
    lines.push(`${pad(indent)}kind: ${renderValue(this.kind, indent)}`);
    lines.push(`${pad(indent)}metadata:`);
    renderObject(
      {
        name: this.metadata.name,
        namespace: this.metadata.namespace,
        uid: this.metadata.uid,
        labels: Object.keys(this.metadata.labels).length > 0 ? this.metadata.labels : undefined,
        annotations: Object.keys(this.metadata.annotations).length > 0 ? this.metadata.annotations : undefined,
        creationTimestamp: this.metadata.creationTimestamp,
        ownerReferences: this.metadata.ownerReferences.length > 0 ? this.metadata.ownerReferences : undefined,
      },
      indent + 1
    );
    lines.push(`${pad(indent)}spec:`);
    renderObject(this.spec, indent + 1);
    lines.push(`${pad(indent)}status:`);
    renderObject(this.status, indent + 1);

    return lines.join('\n');
  }

  clone() {
    const cloned = new ResourceBase(this.kind, this.apiVersion, this.metadata.name, this.metadata.namespace);
    cloned.metadata = JSON.parse(JSON.stringify(this.metadata));
    cloned.metadata.uid = generateUID();
    cloned.spec = JSON.parse(JSON.stringify(this.spec));
    cloned.status = JSON.parse(JSON.stringify(this.status));
    cloned._events = [];
    return cloned;
  }

  equals(other) {
    if (!other || !(other instanceof ResourceBase)) return false;
    return this.metadata.uid === other.metadata.uid;
  }

  toString() {
    return `${this.kind}/${this.metadata.namespace}/${this.metadata.name}`;
  }
}

