export class ContextMenu {
  constructor() {
    this.container = null;
    this.visible = false;
    this.resource = null;
    this._boundClose = this._onClickOutside.bind(this);
    this._boundKeydown = this._onKeydown.bind(this);
    this._boundContextMenu = this._onContextMenu.bind(this);
  }

  init() {
    this.container = document.createElement('div');
    this.container.id = 'context-menu';
    this.container.className = 'fixed z-50 hidden';
    document.body.appendChild(this.container);

    const engine = window.game?.engine;
    if (engine) {
      engine.on('resource:contextmenu', (data) => {
        this.resource = window.game?.cluster?.getResource(data.uid);
        if (this.resource) this.show(data.x, data.y);
      });
    }

    document.addEventListener('contextmenu', this._boundContextMenu);
  }

  _onContextMenu(e) {
    if (e.target.closest('#context-menu')) return;
    if (this.visible) {
      e.preventDefault();
      this.hide();
    }
  }

  show(x, y) {
    if (!this.resource) return;

    const kind = this.resource.kind || 'Unknown';
    const name = this.resource.metadata?.name || 'unnamed';
    const groups = ACTION_MAP[kind] || DEFAULT_ACTIONS;

    this.container.innerHTML = `
      <div class="backdrop-blur-xl bg-gray-900/95 border border-white/10 rounded-lg shadow-2xl overflow-hidden min-w-[180px]">
        <div class="px-3 py-2 border-b border-white/5">
          <div class="text-white/90 text-xs font-medium truncate">${this._escapeHTML(name)}</div>
          <div class="text-white/30 text-[10px]">${this._escapeHTML(kind)}</div>
        </div>
        ${groups.map((group, gi) => `
          ${gi > 0 ? '<div class="h-px bg-white/5"></div>' : ''}
          <div class="py-1">
            ${group.actions.map(action => `
              <button class="w-full flex items-center justify-between px-3 py-1.5 text-xs transition-colors ${action.danger ? 'text-red-400 hover:bg-red-400/10' : 'text-white/70 hover:bg-white/5'}" data-event="${action.event}">
                <span>${this._escapeHTML(action.label)}</span>
                <span class="text-white/20 text-[10px] ml-4">${action.shortcut}</span>
              </button>
            `).join('')}
          </div>
        `).join('')}
      </div>
    `;

    const rect = this.container.firstElementChild.getBoundingClientRect();
    const viewW = window.innerWidth;
    const viewH = window.innerHeight;

    const finalX = x + 200 > viewW ? x - 200 : x;
    const finalY = y + (rect.height || 200) > viewH ? y - (rect.height || 200) : y;

    this.container.style.left = `${Math.max(0, finalX)}px`;
    this.container.style.top = `${Math.max(0, finalY)}px`;
    this.container.classList.remove('hidden');
    this.visible = true;

    this.container.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-event]');
      if (!btn) return;
      this._executeAction(btn.dataset.event);
      this.hide();
    });

    document.addEventListener('click', this._boundClose);
    document.addEventListener('keydown', this._boundKeydown);
  }

  hide() {
    this.container.classList.add('hidden');
    this.visible = false;
    this.resource = null;
    document.removeEventListener('click', this._boundClose);
    document.removeEventListener('keydown', this._boundKeydown);
  }

  _onClickOutside(e) {
    if (!this.container.contains(e.target)) {
      this.hide();
    }
  }

  _onKeydown(e) {
    if (e.key === 'Escape') {
      this.hide();
      return;
    }

    if (!this.resource) return;
    const kind = this.resource.kind || 'Unknown';
    const groups = ACTION_MAP[kind] || DEFAULT_ACTIONS;

    for (const group of groups) {
      for (const action of group.actions) {
        if (action.shortcut.toLowerCase() === e.key.toLowerCase() ||
            (action.shortcut === 'Del' && (e.key === 'Delete' || e.key === 'Backspace'))) {
          e.preventDefault();
          this._executeAction(action.event);
          this.hide();
          return;
        }
      }
    }
  }

  _executeAction(event) {
    if (!this.resource) return;
    const engine = window.game?.engine;
    const cluster = window.game?.cluster;
    const gameEngine = window.game?.gameEngine;
    if (!engine) return;

    const uid = this.resource.metadata?.uid;
    const kind = this.resource.kind;
    const name = this.resource.metadata?.name;
    const namespace = this.resource.metadata?.namespace;

    switch (event) {
      case 'resource:delete':
        if (gameEngine) {
          gameEngine.queueCommand({ type: 'delete', kind, name, namespace });
        } else if (cluster) {
          cluster.remove(uid);
        }
        break;
      case 'resource:describe':
        engine.emit('resource:selected', { uid });
        break;
      case 'deployment:scale':
        engine.emit('ui:scale-dialog', { uid, kind, name, namespace });
        break;
      case 'deployment:restart':
        if (gameEngine) {
          gameEngine.queueCommand({ type: 'rollout', subcommand: 'restart', kind, name, namespace });
        }
        break;
      case 'deployment:rollback':
        if (gameEngine) {
          gameEngine.queueCommand({ type: 'rollout', subcommand: 'undo', kind, name, namespace });
        }
        break;
      case 'node:cordon':
        if (gameEngine) gameEngine.queueCommand({ type: 'cordon', name });
        break;
      case 'node:uncordon':
        if (gameEngine) gameEngine.queueCommand({ type: 'uncordon', name });
        break;
      case 'node:drain':
        if (gameEngine) gameEngine.queueCommand({ type: 'drain', name });
        break;
      case 'pod:logs':
        engine.emit('ui:run-command', { command: namespace ? `logs ${name} -n ${namespace}` : `logs ${name}` });
        break;
      case 'pod:exec':
        engine.emit('ui:run-command', { command: namespace ? `exec -it ${name} -n ${namespace} -- /bin/sh` : `exec -it ${name} -- /bin/sh` });
        break;
      default:
        engine.emit(event, { uid, kind, name, namespace });
        break;
    }
  }

  _escapeHTML(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  destroy() {
    document.removeEventListener('contextmenu', this._boundContextMenu);
    document.removeEventListener('click', this._boundClose);
    document.removeEventListener('keydown', this._boundKeydown);
    this.container?.remove();
  }
}

const SANDBOX_STATE = {
  IDLE: 'idle',
  PLAYING: 'playing',
  PAUSED: 'paused'
};

const ALL_RESOURCE_TYPES = [
  'Namespace', 'Pod', 'Deployment', 'ReplicaSet', 'StatefulSet', 'DaemonSet',
  'Job', 'CronJob', 'Service', 'Ingress', 'NetworkPolicy', 'ConfigMap',
  'Secret', 'PersistentVolume', 'PersistentVolumeClaim', 'StorageClass',
  'HorizontalPodAutoscaler', 'PodDisruptionBudget', 'ResourceQuota',
  'LimitRange', 'Role', 'ClusterRole', 'RoleBinding', 'ClusterRoleBinding',
  'ServiceAccount', 'Node'
];

class SandboxMode {
  constructor(gameEngine, scoringEngine) {
    this.gameEngine = gameEngine;
    this.scoringEngine = scoringEngine;
    this.state = SANDBOX_STATE.IDLE;
    this.startTime = 0;
    this.elapsedTime = 0;
    this.ticker = null;
    this.resourceCount = 0;
    this.architectureScore = null;
    this.autoScoreInterval = null;
  }

  start(initialNodes) {
    this.state = SANDBOX_STATE.PLAYING;
    this.startTime = Date.now();
    this.elapsedTime = 0;
    this.resourceCount = 0;
    this.architectureScore = null;

    this.setupCluster(initialNodes || 3);

    this.ticker = setInterval(() => this.update(), 1000);
    this.autoScoreInterval = setInterval(() => this.refreshArchitectureScore(), 10000);

    this.gameEngine.emit('sandbox:started', {
      availableResources: ALL_RESOURCE_TYPES,
      nodeCount: initialNodes || 3
    });
  }

  setupCluster(nodeCount) {
    const clusterState = this.gameEngine.cluster;
    if (!clusterState) return;

    clusterState.clear();

    for (let i = 1; i <= nodeCount; i++) {
      clusterState.addResource({
        kind: 'Node',
        name: `sandbox-node-${i}`,
        metadata: { name: `sandbox-node-${i}`, namespace: 'default', labels: { role: 'worker' } },
        spec: { cpu: '16', memory: '32Gi', status: 'Ready' },
        status: { phase: 'Running' }
      });
    }

  }

  update() {
    if (this.state !== SANDBOX_STATE.PLAYING) return;

    this.elapsedTime = (Date.now() - this.startTime) / 1000;

    const state = this.gameEngine.cluster;
    if (state) {
      const allResources = state.getAllResources ? state.getAllResources() : [];
      this.resourceCount = allResources.length;
    }

    this.gameEngine.emit('sandbox:update', {
      elapsedTime: Math.round(this.elapsedTime),
      resourceCount: this.resourceCount,
      architectureScore: this.architectureScore ? this.architectureScore.total : null
    });
  }

  addResource(kind, name, spec) {
    const state = this.gameEngine.cluster;
    if (!state) return false;

    if (!ALL_RESOURCE_TYPES.includes(kind)) return false;

    const resource = {
      kind,
      name,
      metadata: {
        name,
        namespace: spec?.namespace || 'default',
        labels: spec?.labels || {},
      },
      spec: spec || {},
      status: { phase: 'Running' },
    };

    state.addResource(resource);
    this.resourceCount++;

    this.gameEngine.emit('resource:created', {
      kind,
      name,
      mode: 'sandbox',
      concurrentPods: kind === 'Pod' ? (state.getResourcesByKind('Pod') || []).length : undefined,
      nodeCount: kind === 'Node' ? (state.getResourcesByKind('Node') || []).length : undefined,
    });

    return true;
  }

  removeResource(kind, name) {
    const state = this.gameEngine.cluster;
    if (!state) return false;

    const removed = state.removeResource(kind, name);
    if (removed) {
      this.resourceCount--;
      this.gameEngine.emit('resource:removed', { kind, name, mode: 'sandbox' });
    }
    return removed;
  }

  getArchitectureScore() {
    const state = this.gameEngine.cluster;
    if (!state) return null;

    this.architectureScore = this.scoringEngine.calculateArchitectureScore(state);

    this.gameEngine.emit('sandbox:architecture-score', {
      total: this.architectureScore.total,
      categories: Object.entries(this.architectureScore.categories).map(([key, val]) => ({
        name: key,
        score: val.score,
        recommendations: val.recommendations
      }))
    });

    return this.architectureScore;
  }

  refreshArchitectureScore() {
    if (this.state !== SANDBOX_STATE.PLAYING) return;
    this.getArchitectureScore();
  }

  exportClusterYAML() {
    const state = this.gameEngine.cluster;
    if (!state) return '';

    const allResources = state.getAllResources ? state.getAllResources() : [];
    const documents = [];

    for (const resource of allResources) {
      const doc = {
        apiVersion: this.getApiVersion(resource.kind),
        kind: resource.kind,
        metadata: {
          name: resource.name || resource.metadata?.name,
          namespace: resource.metadata?.namespace || 'default'
        },
        spec: this.cleanSpec(resource.spec)
      };

      if (resource.metadata?.labels && Object.keys(resource.metadata.labels).length > 0) {
        doc.metadata.labels = resource.metadata.labels;
      }

      documents.push(doc);
    }

    const yaml = documents.map((doc) => this.toYAML(doc)).join('\n---\n');

    this.gameEngine.emit('sandbox:yaml-exported', { resourceCount: documents.length });
    this.gameEngine.emit('yaml:viewed', {});

    return yaml;
  }

  getApiVersion(kind) {
    const versionMap = {
      Pod: 'v1', Service: 'v1', Namespace: 'v1', ConfigMap: 'v1', Secret: 'v1',
      PersistentVolume: 'v1', PersistentVolumeClaim: 'v1', ServiceAccount: 'v1',
      Node: 'v1', ResourceQuota: 'v1', LimitRange: 'v1',
      Deployment: 'apps/v1', ReplicaSet: 'apps/v1', StatefulSet: 'apps/v1', DaemonSet: 'apps/v1',
      Job: 'batch/v1', CronJob: 'batch/v1',
      Ingress: 'networking.k8s.io/v1', NetworkPolicy: 'networking.k8s.io/v1',
      StorageClass: 'storage.k8s.io/v1',
      HorizontalPodAutoscaler: 'autoscaling/v2',
      PodDisruptionBudget: 'policy/v1',
      Role: 'rbac.authorization.k8s.io/v1',
      ClusterRole: 'rbac.authorization.k8s.io/v1',
      RoleBinding: 'rbac.authorization.k8s.io/v1',
      ClusterRoleBinding: 'rbac.authorization.k8s.io/v1'
    };
    return versionMap[kind] || 'v1';
  }

  cleanSpec(spec) {
    if (!spec) return {};
    return Object.fromEntries(
      Object.entries(spec).filter(([key, value]) => key !== 'status' && value != null)
    );
  }

  toYAML(obj, indent = 0) {
    const pad = '  '.repeat(indent);
    let result = '';

    if (Array.isArray(obj)) {
      for (const item of obj) {
        if (typeof item === 'object' && item !== null) {
          result += `${pad}-\n${this.toYAML(item, indent + 1)}`;
        } else {
          result += `${pad}- ${item}\n`;
        }
      }
    } else if (typeof obj === 'object' && obj !== null) {
      for (const [key, value] of Object.entries(obj)) {
        if (typeof value === 'object' && value !== null) {
          if (Array.isArray(value) && value.length === 0) {
            result += `${pad}${key}: []\n`;
          } else if (typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length === 0) {
            result += `${pad}${key}: {}\n`;
          } else {
            result += `${pad}${key}:\n${this.toYAML(value, indent + 1)}`;
          }
        } else {
          const val = typeof value === 'string' && (value.includes(':') || value.includes('#'))
            ? `"${value}"` : value;
          result += `${pad}${key}: ${val}\n`;
        }
      }
    }

    return result;
  }

  pause() {
    if (this.state !== SANDBOX_STATE.PLAYING) return;
    this.state = SANDBOX_STATE.PAUSED;
    this.gameEngine.emit('sandbox:paused', {});
  }

  resume() {
    if (this.state !== SANDBOX_STATE.PAUSED) return;
    this.state = SANDBOX_STATE.PLAYING;
    this.gameEngine.emit('sandbox:resumed', {});
  }

  getStatus() {
    return {
      state: this.state,
      elapsedTime: Math.round(this.elapsedTime),
      resourceCount: this.resourceCount,
      availableResources: ALL_RESOURCE_TYPES,
      architectureScore: this.architectureScore
    };
  }

  stopTicking() {
    if (this.ticker) {
      clearInterval(this.ticker);
      this.ticker = null;
    }
    if (this.autoScoreInterval) {
      clearInterval(this.autoScoreInterval);
      this.autoScoreInterval = null;
    }
  }

  exit() {
    this.stopTicking();
    this.state = SANDBOX_STATE.IDLE;
    this.gameEngine.emit('sandbox:exited', {});
  }

  destroy() {
    this.stopTicking();
    this.gameEngine = null;
    this.scoringEngine = null;
  }
}

export { SandboxMode, SANDBOX_STATE, ALL_RESOURCE_TYPES };

import { CAMPAIGN_LEVELS, CHAPTERS } from '../data/CampaignLevels.js';

const CAMPAIGN_STATE = {
  MENU: 'menu',
  LOADING: 'loading',
  PLAYING: 'playing',
  PAUSED: 'paused',
  COMPLETED: 'completed',
  FAILED: 'failed'
};

class CampaignMode {
  constructor(gameEngine, incidentEngine, scoringEngine) {
    this.gameEngine = gameEngine;
    this.incidentEngine = incidentEngine;
    this.scoringEngine = scoringEngine;
    this.state = CAMPAIGN_STATE.MENU;
    this.currentLevel = null;
    this.currentLevelDef = null;
    this.objectiveProgress = [];
    this.startTime = 0;
    this.elapsedTime = 0;
    this.pausedTime = 0;
    this.pauseStart = 0;
    this.ticker = null;
    this.hadFailures = false;
    this.usedHints = false;
    this.tutorialStep = 0;
    this.tutorialActive = false;
    this.levelRetryCount = 0;

    this.gameEngine.campaignLevels = CAMPAIGN_LEVELS;
  }

  getLevels() {
    const progress = this.scoringEngine.getProgress();
    return CAMPAIGN_LEVELS.map((level) => {
      const levelProgress = progress.campaignProgress[level.id];
      const previousCompleted = level.id === 1 ||
        (progress.campaignProgress[level.id - 1]?.completed);

      const locked = !previousCompleted;
      const completed = levelProgress?.completed || false;
      const stars = levelProgress?.stars || 0;
      const bestTime = levelProgress?.bestTime || null;

      return {
        id: level.id,
        title: level.title,
        chapter: level.chapter,
        chapterName: level.chapterName,
        description: level.description,
        objectives: level.objectives,
        locked,
        completed,
        stars,
        bestTime,
      };
    });
  }

  getChapters() {
    const progress = this.scoringEngine.getProgress();
    return CHAPTERS.map((chapter) => {
      const levels = chapter.levels.map((lid) => {
        const lp = progress.campaignProgress[lid];
        return { id: lid, completed: lp?.completed || false, stars: lp?.stars || 0 };
      });

      const totalStars = levels.reduce((sum, l) => sum + l.stars, 0);
      const maxStars = levels.length * 3;
      const completed = levels.every((l) => l.completed);

      return {
        id: chapter.id,
        name: chapter.name,
        description: chapter.description,
        levels,
        totalStars,
        maxStars,
        completed,
      };
    });
  }

  startLevel(levelId) {
    const levelDef = CAMPAIGN_LEVELS.find((l) => l.id === levelId);
    if (!levelDef) return false;

    const progress = this.scoringEngine.getProgress();
    if (levelId > 1 && !progress.campaignProgress[levelId - 1]?.completed) {
      return false;
    }

    this.currentLevel = levelId;
    this.currentLevelDef = levelDef;
    this.state = CAMPAIGN_STATE.LOADING;
    this.hadFailures = false;
    this.usedHints = false;
    this.tutorialStep = 0;
    this.tutorialActive = false;
    this.pausedTime = 0;

    this.objectiveProgress = levelDef.objectives.map((obj) => ({
      ...obj,
      current: 0,
      target: obj.count || 1,
      completed: false
    }));

    this.setupCluster(levelDef);
    this.incidentEngine.reset();

    if (levelDef.incidents.length > 0) {
      this.incidentEngine.loadScriptedIncidents(levelDef.incidents);
    }

    if (levelDef.tutorial) {
      this.tutorialActive = true;
      this.tutorialStep = 0;
    }

    this.state = CAMPAIGN_STATE.PLAYING;
    this.startTime = Date.now();
    this.incidentEngine.start('campaign');

    this.ticker = setInterval(() => this.update(), 1000);

    const objectives = this.objectiveProgress;

    this.gameEngine.emit('campaign:level-started', {
      levelId: levelDef.id,
      title: levelDef.title,
      chapter: levelDef.chapter,
      chapterName: levelDef.chapterName,
      objectives,
      availableResources: levelDef.availableResources,
      tutorial: levelDef.tutorial,
    });

    return true;
  }

  setupCluster(levelDef) {
    const clusterState = this.gameEngine.cluster;
    if (!clusterState) return;

    clusterState.clear();

    for (const resource of levelDef.startingResources) {
      const ns = resource.spec?.namespace || 'default';
      const defaultLabels = { app: resource.name };
      const added = clusterState.addResource({
        kind: resource.kind,
        name: resource.name,
        metadata: {
          name: resource.name,
          namespace: ns,
          labels: { ...defaultLabels }
        },
        spec: resource.spec || {},
        status: { phase: 'Running' }
      });

      if (resource.kind === 'Node' && added) {
        added.setCondition('Ready', 'True', 'KubeletReady');
      }

      if (resource.kind === 'Deployment' && added && !added.spec.selector) {
        added.spec.selector = { matchLabels: { ...defaultLabels } };
      }
    }
  }

  update() {
    if (this.state !== CAMPAIGN_STATE.PLAYING) return;

    this.elapsedTime = (Date.now() - this.startTime - this.pausedTime) / 1000;
    this.updateObjectives();
    this.checkCompletion();
    this.checkFailure();

    this.gameEngine.emit('campaign:update', {
      levelId: this.currentLevel,
      elapsedTime: this.elapsedTime,
      objectives: this.objectiveProgress,
      clusterHealth: this.incidentEngine.getClusterHealth()
    });
  }

  updateObjectives() {
    const state = this.gameEngine.cluster;
    if (!state) return;

    for (const obj of this.objectiveProgress) {
      if (obj.completed) continue;

      switch (obj.type) {
        case 'deploy': {
          const resources = state.getResourcesByKind(obj.kind) || [];
          obj.current = resources.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'scale': {
          const deployments = state.getResourcesByKind(obj.kind) || [];
          const scaled = deployments.find((d) => (d.spec?.replicas || 0) >= obj.replicas);
          obj.current = scaled ? obj.replicas : 0;
          obj.target = obj.replicas;
          obj.completed = !!scaled;
          break;
        }
        case 'resolve': {
          const stats = this.incidentEngine.getStats();
          const resolved = stats.totalResolved;
          obj.current = Math.min(resolved, obj.target);
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'uptime': {
          const health = this.incidentEngine.getClusterHealth();
          obj.current = Math.round(health);
          obj.target = obj.percentage;
          obj.completed = health >= obj.percentage;
          break;
        }
        case 'distribute': {
          const pods = state.getResourcesByKind('Pod') || [];
          const nodeSet = new Set(pods.map((p) => p.spec?.nodeName).filter(Boolean));
          obj.current = nodeSet.size;
          obj.target = obj.minNodes;
          obj.completed = nodeSet.size >= obj.minNodes;
          break;
        }
        case 'replicas': {
          const deps = state.getResourcesByKind('Deployment') || [];
          const allMeetMin = deps.every((d) => (d.spec?.replicas || 0) >= obj.minPerDeployment);
          obj.current = allMeetMin ? obj.target : 0;
          obj.completed = allMeetMin && deps.length > 0;
          break;
        }
        case 'coverage': {
          const nodes = state.getResourcesByKind('Node') || [];
          const daemonSets = state.getResourcesByKind('DaemonSet') || [];
          if (daemonSets.length > 0 && nodes.length > 0) {
            const pods = state.getResourcesByKind('Pod') || [];
            const dsPods = pods.filter((p) =>
              p.metadata?.ownerReferences?.some((ref) => ref.kind === 'DaemonSet')
            );
            const coveredNodes = new Set(dsPods.map((p) => p.spec?.nodeName).filter(Boolean));
            obj.current = coveredNodes.size;
            obj.target = nodes.length;
            obj.completed = coveredNodes.size >= nodes.length;
          }
          break;
        }
        case 'complete': {
          const jobs = state.getResourcesByKind(obj.kind) || [];
          const completed = jobs.filter((j) => j.status?.phase === 'Complete');
          obj.current = completed.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'update': {
          const deps = state.getResourcesByKind(obj.kind) || [];
          const updated = deps.filter((d) => d.status?.updatedReplicas > 0);
          obj.current = updated.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'rollback': {
          obj.current = state._rollbackCount || 0;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'connect': {
          const services = state.getResourcesByKind('Service') || [];
          const hasConnection = services.some((s) =>
            s.spec?.selector && Object.keys(s.spec.selector).length > 0 &&
            (s.name === obj.to + '-svc' || s.name === obj.to)
          );
          obj.current = hasConnection ? 1 : 0;
          obj.completed = hasConnection;
          break;
        }
        case 'serviceType': {
          const services = state.getResourcesByKind('Service') || [];
          const matching = services.filter((s) => s.spec?.type === obj.kind);
          obj.current = matching.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'route': {
          const ingresses = state.getResourcesByKind('Ingress') || [];
          const paths = ingresses.flatMap((i) =>
            (i.spec?.rules || []).flatMap((r) => {
              const httpPaths = r.http?.paths || r.paths || [];
              return httpPaths.map((p) => p.path);
            })
          );
          const matched = obj.paths.filter((p) => paths.includes(p));
          obj.current = matched.length;
          obj.target = obj.paths.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'tls': {
          const ingresses = state.getResourcesByKind('Ingress') || [];
          const hasTLS = ingresses.some((i) => i.spec?.tls && i.spec.tls.length > 0);
          obj.current = hasTLS ? 1 : 0;
          obj.completed = hasTLS;
          break;
        }
        case 'isolate': {
          const policies = state.getResourcesByKind('NetworkPolicy') || [];
          const isolated = policies.some((p) => p.spec?.namespace === obj.namespace || p.metadata?.namespace === obj.namespace);
          obj.current = isolated ? 1 : 0;
          obj.completed = isolated;
          break;
        }
        case 'allow': {
          const policies = state.getResourcesByKind('NetworkPolicy') || [];
          obj.current = policies.length > 0 ? 1 : 0;
          obj.completed = policies.length > 0;
          break;
        }
        case 'investigate': {
          const active = this.incidentEngine.getActiveIncidents();
          const resolved = this.incidentEngine.resolvedIncidents || [];
          const allIncidents = [...active, ...resolved.map(i => ({
            name: i.name,
            investigationProgress: i.investigationProgress
          }))];
          const incident = allIncidents.find((i) => i.name === obj.incidentType);
          obj.current = incident?.investigationProgress >= 0.5 ? 1 : 0;
          obj.completed = obj.current >= 1;
          break;
        }
        case 'verify': {
          const health = this.incidentEngine.getClusterHealth();
          obj.current = health >= 90 ? 1 : 0;
          obj.completed = health >= 90;
          break;
        }
        case 'mount':
        case 'envFrom': {
          const resources = state.getResourcesByKind(obj.kind) || [];
          obj.current = Math.min(resources.length, obj.target);
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'noConfigMap': {
          const cms = state.getResourcesByKind('ConfigMap') || [];
          const hasSensitive = cms.some((cm) => {
            const data = cm.spec?.data || {};
            return Object.keys(data).some((k) => /password|secret|key|token/i.test(k));
          });
          obj.current = hasSensitive ? 0 : 1;
          obj.completed = !hasSensitive;
          break;
        }
        case 'bound': {
          const pvcs = state.getResourcesByKind(obj.kind) || [];
          const bound = pvcs.filter((p) => p.status?.phase === 'Bound');
          obj.current = bound.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'headless': {
          const services = state.getResourcesByKind('Service') || [];
          const headless = services.filter((s) => s.spec?.clusterIP === 'None');
          obj.current = headless.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'stable': {
          const sts = state.getResourcesByKind('StatefulSet') || [];
          obj.current = sts.length > 0 ? 1 : 0;
          obj.completed = sts.length > 0;
          break;
        }
        case 'resources': {
          const deps = state.getResourcesByKind('Deployment') || [];
          const configured = deps.filter((d) => d.spec?.resources?.requests && d.spec?.resources?.limits);
          obj.current = configured.length;
          obj.target = deps.length;
          obj.completed = configured.length === deps.length && deps.length > 0;
          break;
        }
        case 'probes': {
          const deps = state.getResourcesByKind('Deployment') || [];
          const withProbes = deps.filter((d) => d.spec?.livenessProbe && d.spec?.readinessProbe);
          obj.current = withProbes.length;
          obj.target = deps.length;
          obj.completed = withProbes.length === deps.length && deps.length > 0;
          break;
        }
        case 'hpa': {
          const hpas = state.getResourcesByKind('HorizontalPodAutoscaler') || [];
          obj.current = hpas.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'leastPrivilege': {
          const roles = state.getResourcesByKind('Role') || [];
          const hasWildcard = roles.some((r) => r.spec?.rules?.some((rule) => rule.verbs?.includes('*')));
          obj.current = hasWildcard ? 0 : 1;
          obj.completed = !hasWildcard;
          break;
        }
        case 'reschedule': {
          obj.current = state._rescheduledCount || 0;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'pdb': {
          const pdbs = state.getResourcesByKind('PodDisruptionBudget') || [];
          obj.current = pdbs.length;
          obj.completed = obj.current >= obj.target;
          break;
        }
        case 'architectureScore': {
          const score = this.scoringEngine.calculateArchitectureScore(state);
          obj.current = score.total;
          obj.target = obj.minScore;
          obj.completed = score.total >= obj.minScore;
          break;
        }
      }
    }
  }

  checkCompletion() {
    if (this.objectiveProgress.every((obj) => obj.completed)) {
      this.completeLevel();
    }
  }

  checkFailure() {
    const health = this.incidentEngine.getClusterHealth();
    if (health <= 0) {
      this.hadFailures = true;
    }

    const activeIncidents = this.incidentEngine.getActiveIncidents();
    if (activeIncidents.some((inc) => inc.severity >= 4)) {
      this.hadFailures = true;
    }
  }

  completeLevel() {
    this.state = CAMPAIGN_STATE.COMPLETED;
    this.stopTicking();
    this.incidentEngine.stop();

    const completionTime = this.elapsedTime;
    const totalObjectives = this.objectiveProgress.length;
    const completedObjectives = this.objectiveProgress.filter((o) => o.completed).length;
    const efficiency = completedObjectives / totalObjectives;

    const result = this.scoringEngine.completeCampaignLevel(
      this.currentLevel,
      completionTime,
      efficiency,
      this.hadFailures,
      this.usedHints
    );

    const completionData = {
      levelId: this.currentLevel,
      title: this.currentLevelDef.title,
      stars: result.stars,
      xpEarned: result.xpEarned,
      completionTime: Math.round(completionTime),
      efficiency: Math.round(efficiency * 100),
      hadFailures: this.hadFailures,
      nextLevel: this.currentLevelDef.nextLevel
    };

    this.gameEngine.emit('campaign:level-completed', completionData);
    this.gameEngine.emit('mode:level-complete', {
      ...completionData,
      message: `Completed in ${Math.round(completionTime)}s with ${Math.round(efficiency * 100)}% efficiency. +${result.xpEarned} XP`
    });

    return result;
  }

  failLevel(reason) {
    this.state = CAMPAIGN_STATE.FAILED;
    this.stopTicking();
    this.incidentEngine.stop();
    this.levelRetryCount++;

    this.scoringEngine.progress.stats.levelRetries = (this.scoringEngine.progress.stats.levelRetries || 0) + 1;
    this.scoringEngine.saveProgress();

    this.gameEngine.emit('campaign:level-failed', {
      levelId: this.currentLevel,
      title: this.currentLevelDef.title,
      reason,
      elapsedTime: Math.round(this.elapsedTime),
    });
  }

  retryLevel() {
    if (!this.currentLevel) return false;
    return this.startLevel(this.currentLevel);
  }

  nextLevel() {
    if (!this.currentLevelDef || !this.currentLevelDef.nextLevel) return false;
    return this.startLevel(this.currentLevelDef.nextLevel);
  }

  pause() {
    if (this.state !== CAMPAIGN_STATE.PLAYING) return;
    this.state = CAMPAIGN_STATE.PAUSED;
    this.pauseStart = Date.now();
    this.incidentEngine.pause();
    this.gameEngine.emit('campaign:paused', { levelId: this.currentLevel });
  }

  resume() {
    if (this.state !== CAMPAIGN_STATE.PAUSED) return;
    this.state = CAMPAIGN_STATE.PLAYING;
    this.pausedTime += Date.now() - this.pauseStart;
    this.incidentEngine.resume();
    this.gameEngine.emit('campaign:resumed', { levelId: this.currentLevel });
  }

  useHint(index) {
    if (!this.currentLevelDef) return null;
    if (index < 0 || index >= this.currentLevelDef.hints.length) return null;

    this.usedHints = true;
    const hint = this.currentLevelDef.hints[index];

    this.gameEngine.emit('campaign:hint-used', {
      levelId: this.currentLevel,
      hintIndex: index,
      hint,
    });

    return hint;
  }

  advanceTutorial() {
    if (!this.tutorialActive || !this.currentLevelDef?.tutorial) return null;

    const steps = this.currentLevelDef.tutorial.steps;
    if (this.tutorialStep >= steps.length) {
      this.tutorialActive = false;
      this.gameEngine.emit('campaign:tutorial-completed', { levelId: this.currentLevel });
      return null;
    }

    const step = steps[this.tutorialStep];
    this.tutorialStep++;

    this.gameEngine.emit('campaign:tutorial-step', {
      levelId: this.currentLevel,
      step: this.tutorialStep,
      totalSteps: steps.length,
      target: step.target,
      text: step.text
    });

    return step;
  }

  skipTutorial() {
    this.tutorialActive = false;
    this.gameEngine.emit('campaign:tutorial-skipped', { levelId: this.currentLevel });
  }

  getCompletionPercentage() {
    if (this.objectiveProgress.length === 0) return 0;
    const completed = this.objectiveProgress.filter((o) => o.completed).length;
    return Math.round((completed / this.objectiveProgress.length) * 100);
  }

  getStatus() {
    return {
      state: this.state,
      currentLevel: this.currentLevel,
      levelTitle: this.currentLevelDef?.title || null,
      chapter: this.currentLevelDef?.chapter || null,
      chapterName: this.currentLevelDef?.chapterName || null,
      elapsedTime: Math.round(this.elapsedTime),
      objectives: this.objectiveProgress,
      completionPercentage: this.getCompletionPercentage(),
      clusterHealth: this.incidentEngine.getClusterHealth(),
      activeIncidents: this.incidentEngine.getActiveIncidents().length,
      tutorialActive: this.tutorialActive,
      tutorialStep: this.tutorialStep,
      hints: this.currentLevelDef?.hints || [],
      availableResources: this.currentLevelDef?.availableResources || [],
    };
  }

  stopTicking() {
    if (this.ticker) {
      clearInterval(this.ticker);
      this.ticker = null;
    }
  }

  exitToMenu() {
    this.stopTicking();
    this.incidentEngine.stop();
    this.state = CAMPAIGN_STATE.MENU;
    this.currentLevel = null;
    this.currentLevelDef = null;
    this.gameEngine.emit('campaign:exit-to-menu', {});
  }

  destroy() {
    this.stopTicking();
    this.gameEngine = null;
    this.incidentEngine = null;
    this.scoringEngine = null;
  }
}

export { CampaignMode, CAMPAIGN_STATE };

import { ResourceBase } from './ResourceBase.js';

export class Service extends ResourceBase {
  constructor(metadata = {}) {
    super('Service', metadata);
    this.spec = {
      type: metadata.serviceType || 'ClusterIP',
      selector: metadata.selector || { app: metadata.name },
      ports: metadata.ports || [{ name: 'http', port: 80, targetPort: 8080, protocol: 'TCP' }],
      clusterIP: metadata.clusterIP || this._generateClusterIP(),
      externalIPs: metadata.externalIPs || [],
      sessionAffinity: metadata.sessionAffinity || 'None',
      loadBalancerIP: null,
      nodePort: null
    };

    if (this.spec.type === 'NodePort' || this.spec.type === 'LoadBalancer') {
      this.spec.ports = this.spec.ports.map(p => ({
        ...p,
        nodePort: p.nodePort || (30000 + Math.floor(Math.random() * 2767)),
      }));
    }

    if (this.spec.type === 'LoadBalancer') {
      this.loadBalancerPending = true;
      this.loadBalancerTimer = 0;
    }

    this.endpoints = [];
    this.trafficRate = 0;
    this.totalRequests = 0;
    this.setStatus('Active');
  }

  _generateClusterIP() {
    return `10.${96 + Math.floor(Math.random() * 16)}.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 254) + 1}`;
  }

  updateEndpoints(pods) {
    this.endpoints = pods
      .filter(p => p.isReady() && this._matchesSelector(p))
      .map(p => ({
        ip: p.ip,
        nodeName: p.spec.nodeName,
        targetRef: { kind: 'Pod', name: p.metadata.name, uid: p.uid }
      }));
  }

  _matchesSelector(pod) {
    return Object.entries(this.spec.selector).every(([k, v]) => pod.metadata.labels[k] === v);
  }

  routeTraffic() {
    if (this.endpoints.length === 0) return null;
    this.totalRequests++;
    const idx = Math.floor(Math.random() * this.endpoints.length);
    return this.endpoints[idx];
  }

  tick(deltaTime) {
    super.tick(deltaTime);

    if (this.spec.type === 'LoadBalancer' && this.loadBalancerPending) {
      this.loadBalancerTimer += deltaTime;
      if (this.loadBalancerTimer >= 5) {
        this.loadBalancerPending = false;
        this.spec.loadBalancerIP = `203.0.113.${Math.floor(Math.random() * 254) + 1}`;
        this.addEvent('Normal', 'EnsuringLoadBalancer', 'Ensuring load balancer');
        this.addEvent('Normal', 'EnsuredLoadBalancer', `Ensured load balancer with IP ${this.spec.loadBalancerIP}`);
      }
    }

    this.trafficRate = Math.max(0, this.trafficRate + (Math.random() - 0.5) * 5);
  }

  getShape() {
    if (this.spec.type === 'LoadBalancer') return 'circle-cloud';
    if (this.spec.type === 'NodePort') return 'circle-port';
    return 'circle';
  }

  getColor() { return '#326CE5'; }

  toYAML() {
    let portSection = this.spec.ports.map(p => {
      let s = `  - name: ${p.name}
    port: ${p.port}
    targetPort: ${p.targetPort}
    protocol: ${p.protocol}`;
      if (p.nodePort) s += `\n    nodePort: ${p.nodePort}`;
      return s;
    }).join('\n');

    let statusSection = `  loadBalancer: {}`;
    if (this.spec.type === 'LoadBalancer' && this.spec.loadBalancerIP) {
      statusSection = `  loadBalancer:
    ingress:
    - ip: ${this.spec.loadBalancerIP}`;
    }

    return `apiVersion: v1
kind: Service
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
  labels:
${Object.entries(this.metadata.labels).map(([k, v]) => `    ${k}: "${v}"`).join('\n')}
spec:
  type: ${this.spec.type}
  selector:
${Object.entries(this.spec.selector).map(([k, v]) => `    ${k}: "${v}"`).join('\n')}
  ports:
${portSection}
  clusterIP: ${this.spec.clusterIP}
  sessionAffinity: ${this.spec.sessionAffinity}
status:
${statusSection}`;
  }

  toDescribe() {
    const externalIP = this.spec.type === 'LoadBalancer'
      ? (this.spec.loadBalancerIP || '<pending>')
      : '<none>';

    const endpointsList = this.endpoints.map(e => `${e.ip}:${this.spec.ports[0].targetPort}`).join(', ') || '<none>';

    const lines = [
      `Name:              ${this.metadata.name}`,
      `Namespace:         ${this.metadata.namespace}`,
      `Labels:            ${Object.entries(this.metadata.labels).map(([k, v]) => `${k}=${v}`).join(', ')}`,
      `Selector:          ${Object.entries(this.spec.selector).map(([k, v]) => `${k}=${v}`).join(',')}`,
      `Type:              ${this.spec.type}`,
      `IP:                ${this.spec.clusterIP}`,
      `External IP:       ${externalIP}`,
      `Port:              ${this.spec.ports.map(p => `${p.name} ${p.port}/${p.protocol}`).join(', ')}`,
      `TargetPort:        ${this.spec.ports.map(p => `${p.targetPort}/${p.protocol}`).join(', ')}`,
    ];

    if (this.spec.ports[0]?.nodePort) {
      lines.push(`NodePort:          ${this.spec.ports.map(p => `${p.name} ${p.nodePort}/${p.protocol}`).join(', ')}`);
    }

    lines.push(
      `Endpoints:         ${endpointsList}`,
      `Session Affinity:  ${this.spec.sessionAffinity}`,
      `Events:`,
      ...this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`),
    );

    return lines.join('\n');
  }
}

export class Ingress extends ResourceBase {
  constructor(metadata = {}) {
    super('Ingress', metadata);
    this.spec = {
      ingressClassName: metadata.ingressClassName || 'nginx',
      tls: metadata.tls || [],
      rules: metadata.rules || [
        {
          host: metadata.host || 'app.example.com',
          http: {
            paths: [
              {
                path: '/',
                pathType: 'Prefix',
                backend: {
                  service: { name: metadata.backendService || 'web-service', port: { number: 80 } }
                }
              }
            ]
          }
        }
      ],
      defaultBackend: metadata.defaultBackend || null
    };
    this.loadBalancerIP = null;
    this.loadBalancerTimer = 0;
    this.loadBalancerPending = true;
    this.backendServices = new Map();
    this.requestCount = 0;
    this.setStatus('Active');
  }

  addTLS(hosts, secretName) {
    this.spec.tls.push({ hosts, secretName });
    this.addEvent('Normal', 'UpdatedTLS', `TLS configured for ${hosts.join(', ')}`);
  }

  addRule(host, path, serviceName, servicePort) {
    const existingRule = this.spec.rules.find(r => r.host === host);
    const pathEntry = {
      path,
      pathType: 'Prefix',
      backend: { service: { name: serviceName, port: { number: servicePort } } }
    };
    if (existingRule) {
      existingRule.http.paths.push(pathEntry);
    } else {
      this.spec.rules.push({ host, http: { paths: [pathEntry] } });
    }
    this.addEvent('Normal', 'UpdatedIngress', `Added rule: ${host}${path} -> ${serviceName}:${servicePort}`);
  }

  routeRequest(host, path) {
    this.requestCount++;
    const rule = this.spec.rules.find(r => r.host === host);
    if (!rule) return this.spec.defaultBackend;

    const matchedPath = rule.http.paths
      .sort((a, b) => b.path.length - a.path.length)
      .find(p => path.startsWith(p.path));

    return matchedPath ? matchedPath.backend : this.spec.defaultBackend;
  }

  tick(deltaTime) {
    super.tick(deltaTime);

    if (this.loadBalancerPending) {
      this.loadBalancerTimer += deltaTime;
      if (this.loadBalancerTimer >= 3) {
        this.loadBalancerPending = false;
        this.loadBalancerIP = `203.0.113.${Math.floor(Math.random() * 254) + 1}`;
        this.addEvent('Normal', 'Sync', `Scheduled for sync`);
      }
    }
  }

  getShape() { return 'diamond'; }
  getColor() { return '#8b5cf6'; }

  toYAML() {
    return `apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
  annotations:
    kubernetes.io/ingress.class: ${this.spec.ingressClassName}
spec:
  ingressClassName: ${this.spec.ingressClassName}
${this.spec.tls.length > 0 ? `  tls:
${this.spec.tls.map(t => `  - hosts:
${t.hosts.map(h => `    - ${h}`).join('\n')}
    secretName: ${t.secretName}`).join('\n')}` : ''}
  rules:
${this.spec.rules.map(r => `  - host: ${r.host}
    http:
      paths:
${r.http.paths.map(p => `      - path: ${p.path}
        pathType: ${p.pathType}
        backend:
          service:
            name: ${p.backend.service.name}
            port:
              number: ${p.backend.service.port.number}`).join('\n')}`).join('\n')}
status:
  loadBalancer:
${this.loadBalancerIP ? `    ingress:
    - ip: ${this.loadBalancerIP}` : '    {}'}`;
  }

  toDescribe() {
    return `Name:             ${this.metadata.name}
Namespace:        ${this.metadata.namespace}
Address:          ${this.loadBalancerIP || '<pending>'}
Ingress Class:    ${this.spec.ingressClassName}
Default backend:  ${this.spec.defaultBackend ? `${this.spec.defaultBackend.service.name}:${this.spec.defaultBackend.service.port.number}` : '<default>'}
TLS:
${this.spec.tls.length > 0 ? this.spec.tls.map(t => `  ${t.secretName} terminates ${t.hosts.join(',')}`).join('\n') : '  <none>'}
Rules:
  Host              Path  Backends
  ----              ----  --------
${this.spec.rules.map(r => r.http.paths.map(p => `  ${r.host}  ${p.path}  ${p.backend.service.name}:${p.backend.service.port.number}`).join('\n')).join('\n')}
Events:
${this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`).join('\n')}`;
  }
}

export class NetworkPolicy extends ResourceBase {
  constructor(metadata = {}) {
    super('NetworkPolicy', metadata);
    this.spec = {
      podSelector: { matchLabels: metadata.podSelector || { app: metadata.name } },
      policyTypes: metadata.policyTypes || ['Ingress', 'Egress'],
      ingress: metadata.ingress || [
        {
          from: [
            { podSelector: { matchLabels: { role: 'frontend' } } }
          ],
          ports: [{ protocol: 'TCP', port: 80 }]
        }
      ],
      egress: metadata.egress || [
        {
          to: [
            { podSelector: { matchLabels: { role: 'database' } } }
          ],
          ports: [{ protocol: 'TCP', port: 5432 }]
        }
      ]
    };
    this.affectedPods = [];
    this.blockedConnections = 0;
    this.allowedConnections = 0;
    this.setStatus('Active');
  }

  evaluateIngress(sourcePod, destPod, port) {
    if (!this._matchesPodSelector(destPod)) return true;

    for (const rule of this.spec.ingress) {
      const portMatch = !rule.ports || rule.ports.some(p => p.port === port);
      if (!portMatch) continue;

      for (const from of rule.from) {
        if (from.podSelector && this._labelsMatch(sourcePod.metadata.labels, from.podSelector.matchLabels)) {
          this.allowedConnections++;
          return true;
        }
        if (from.namespaceSelector && this._labelsMatch({ name: sourcePod.metadata.namespace }, from.namespaceSelector.matchLabels)) {
          this.allowedConnections++;
          return true;
        }
      }
    }

    this.blockedConnections++;
    return false;
  }

  evaluateEgress(sourcePod, destPod, port) {
    if (!this._matchesPodSelector(sourcePod)) return true;

    for (const rule of this.spec.egress) {
      const portMatch = !rule.ports || rule.ports.some(p => p.port === port);
      if (!portMatch) continue;

      for (const to of rule.to) {
        if (to.podSelector && this._labelsMatch(destPod.metadata.labels, to.podSelector.matchLabels)) {
          this.allowedConnections++;
          return true;
        }
        if (to.namespaceSelector && this._labelsMatch({ name: destPod.metadata.namespace }, to.namespaceSelector.matchLabels)) {
          this.allowedConnections++;
          return true;
        }
      }
    }

    this.blockedConnections++;
    return false;
  }

  _matchesPodSelector(pod) {
    return this._labelsMatch(pod.metadata.labels, this.spec.podSelector.matchLabels);
  }

  _labelsMatch(labels, selector) {
    return Object.entries(selector).every(([k, v]) => labels[k] === v);
  }

  updateAffectedPods(pods) {
    this.affectedPods = pods.filter(p => this._matchesPodSelector(p));
  }

  getShape() { return 'shield'; }

  getColor() {
    const hasBoth = this.spec.policyTypes.includes('Ingress') && this.spec.policyTypes.includes('Egress');
    return hasBoth ? '#ef4444' : '#22c55e';
  }

  toYAML() {
    return `apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: ${this.metadata.name}
  namespace: ${this.metadata.namespace}
  uid: ${this.uid}
spec:
  podSelector:
    matchLabels:
${Object.entries(this.spec.podSelector.matchLabels).map(([k, v]) => `      ${k}: "${v}"`).join('\n')}
  policyTypes:
${this.spec.policyTypes.map(t => `  - ${t}`).join('\n')}
  ingress:
${this.spec.ingress.map(rule => `  - from:
${rule.from.map(f => {
  if (f.podSelector) return `    - podSelector:\n        matchLabels:\n${Object.entries(f.podSelector.matchLabels).map(([k, v]) => `          ${k}: "${v}"`).join('\n')}`;
  if (f.namespaceSelector) return `    - namespaceSelector:\n        matchLabels:\n${Object.entries(f.namespaceSelector.matchLabels).map(([k, v]) => `          ${k}: "${v}"`).join('\n')}`;
  return '';
}).join('\n')}
    ports:
${rule.ports.map(p => `    - protocol: ${p.protocol}\n      port: ${p.port}`).join('\n')}`).join('\n')}
  egress:
${this.spec.egress.map(rule => `  - to:
${rule.to.map(t => {
  if (t.podSelector) return `    - podSelector:\n        matchLabels:\n${Object.entries(t.podSelector.matchLabels).map(([k, v]) => `          ${k}: "${v}"`).join('\n')}`;
  return '';
}).join('\n')}
    ports:
${rule.ports.map(p => `    - protocol: ${p.protocol}\n      port: ${p.port}`).join('\n')}`).join('\n')}`;
  }

  toDescribe() {
    return `Name:         ${this.metadata.name}
Namespace:    ${this.metadata.namespace}
Spec:
  PodSelector:     ${Object.entries(this.spec.podSelector.matchLabels).map(([k, v]) => `${k}=${v}`).join(',')}
  Allowing ingress traffic:
${this.spec.ingress.map(rule => `    To Port: ${rule.ports.map(p => `${p.port}/${p.protocol}`).join(', ')}
    From:
${rule.from.map(f => {
  if (f.podSelector) return `      PodSelector: ${Object.entries(f.podSelector.matchLabels).map(([k, v]) => `${k}=${v}`).join(',')}`;
  if (f.namespaceSelector) return `      NamespaceSelector: ${Object.entries(f.namespaceSelector.matchLabels).map(([k, v]) => `${k}=${v}`).join(',')}`;
  return '';
}).join('\n')}`).join('\n')}
  Allowing egress traffic:
${this.spec.egress.map(rule => `    To Port: ${rule.ports.map(p => `${p.port}/${p.protocol}`).join(', ')}
    To:
${rule.to.map(t => {
  if (t.podSelector) return `      PodSelector: ${Object.entries(t.podSelector.matchLabels).map(([k, v]) => `${k}=${v}`).join(',')}`;
  return '';
}).join('\n')}`).join('\n')}
  Policy Types: ${this.spec.policyTypes.join(', ')}
Affected Pods: ${this.affectedPods.length}
Blocked:       ${this.blockedConnections}
Allowed:       ${this.allowedConnections}
Events:
${this.events.slice(-10).map(e => `  ${e.type}\t${e.reason}\t${e.message}`).join('\n')}`;
  }
}

import { ResourceBase } from '../resources/ResourceBase.js';

const CLUSTER_SCOPED_KINDS = ['Node', 'Namespace', 'PersistentVolume', 'StorageClass', 'ClusterRole', 'ClusterRoleBinding'];

export function isClusterScopedKind(kind) {
  return CLUSTER_SCOPED_KINDS.includes(kind);
}

const RESOURCE_KINDS = [
  'Node', 'Namespace', 'Pod', 'Deployment', 'ReplicaSet', 'StatefulSet',
  'DaemonSet', 'Job', 'CronJob', 'Service', 'Ingress', 'NetworkPolicy',
  'ConfigMap', 'Secret', 'PersistentVolume', 'PersistentVolumeClaim',
  'StorageClass', 'HorizontalPodAutoscaler', 'Role', 'ClusterRole',
  'RoleBinding', 'ClusterRoleBinding', 'ServiceAccount', 'PodDisruptionBudget',
  'ResourceQuota',
];

const OWNER_CHAINS = {
  Deployment: ['ReplicaSet'],
  ReplicaSet: ['Pod'],
  StatefulSet: ['Pod'],
  DaemonSet: ['Pod'],
  Job: ['Pod'],
  CronJob: ['Job'],
};

export class ClusterState {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.resources = new Map();
    this.relationships = new Map();
    this.reverseRelationships = new Map();
    this.kindIndex = new Map();
    this.namespaceIndex = new Map();
    this.nameIndex = new Map();
    this.labelIndex = new Map();
    this.resourceQuotas = new Map();
    this.limitRanges = new Map();
    this._watchCallbacks = new Map();
    this._batchMode = false;
    this._batchedEvents = [];

    for (const kind of RESOURCE_KINDS) {
      this.kindIndex.set(kind, new Set());
    }

    this._initDefaultNamespaces();
  }

  _initDefaultNamespaces() {
    const defaults = ['default', 'kube-system', 'kube-public', 'kube-node-lease'];
    for (const ns of defaults) {
      const resource = new ResourceBase('Namespace', 'v1', ns, '');
      resource.setPhase('Active');
      resource.setLabel('kubernetes.io/metadata.name', ns);
      this.add(resource);
    }
  }

  get totalResources() {
    return this.resources.size;
  }

  startBatch() {
    this._batchMode = true;
    this._batchedEvents = [];
  }

  flushBatch() {
    this._batchMode = false;
    for (const evt of this._batchedEvents) {
      this._emitEvent(evt.type, evt.resource, evt.extra);
    }
    this._batchedEvents = [];
  }

  _emitEvent(type, resource, extra = {}) {
    const payload = {
      type,
      resource,
      kind: resource.kind,
      name: resource.metadata.name,
      namespace: resource.metadata.namespace,
      uid: resource.metadata.uid,
      timestamp: Date.now(),
      ...extra,
    };
    if (this._batchMode) {
      this._batchedEvents.push({ type, resource, extra });
      return;
    }
    if (this.eventBus) {
      this.eventBus.emit(`cluster:${type}`, payload);
      this.eventBus.emit(`cluster:${type}:${resource.kind}`, payload);
    }
    const watchers = this._watchCallbacks.get(resource.kind) || [];
    for (const cb of watchers) {
      cb(payload);
    }
  }

  add(resource) {
    if (!(resource instanceof ResourceBase)) {
      throw new Error('Resource must be an instance of ResourceBase');
    }
    const existing = this.resources.get(resource.uid);
    if (existing) {
      return this.update(resource.uid, resource);
    }

    this.resources.set(resource.uid, resource);
    this._addToKindIndex(resource);
    this._addToNamespaceIndex(resource);
    this._addToNameIndex(resource);
    this._addToLabelIndex(resource);
    this.relationships.set(resource.uid, new Set());
    this.reverseRelationships.set(resource.uid, new Set());

    for (const ref of resource.metadata.ownerReferences) {
      this._addRelationship(ref.uid, resource.uid);
    }

    this._emitEvent('added', resource);
    return resource;
  }

  update(uid, updates) {
    const resource = this.resources.get(uid);
    if (!resource) return null;

    this._removeFromLabelIndex(resource);

    if (updates instanceof ResourceBase) {
      const oldPhase = resource.status.phase;
      resource.spec = JSON.parse(JSON.stringify(updates.spec));
      resource.status = JSON.parse(JSON.stringify(updates.status));
      Object.assign(resource.metadata.labels, updates.metadata.labels);
      Object.assign(resource.metadata.annotations, updates.metadata.annotations);
      resource._bumpResourceVersion();

      if (oldPhase !== resource.status.phase) {
        resource.recordEvent('Normal', 'PhaseChange', `Phase changed from ${oldPhase} to ${resource.status.phase}`);
      }
    } else if (typeof updates === 'object') {
      if (updates.spec) {
        Object.assign(resource.spec, updates.spec);
        resource.metadata.generation++;
      }
      if (updates.status) {
        const oldPhase = resource.status.phase;
        Object.assign(resource.status, updates.status);
        if (updates.status.conditions) {
          resource.status.conditions = updates.status.conditions;
        }
        if (oldPhase !== resource.status.phase) {
          resource.recordEvent('Normal', 'PhaseChange', `Phase changed from ${oldPhase} to ${resource.status.phase}`);
        }
      }
      if (updates.metadata) {
        if (updates.metadata.labels) Object.assign(resource.metadata.labels, updates.metadata.labels);
        if (updates.metadata.annotations) Object.assign(resource.metadata.annotations, updates.metadata.annotations);
      }
      resource._bumpResourceVersion();
    }

    this._addToLabelIndex(resource);
    this._emitEvent('modified', resource);
    return resource;
  }

  remove(uid) {
    const resource = this.resources.get(uid);
    if (!resource) return null;

    if (resource.metadata.finalizers.length > 0) {
      resource.markForDeletion();
      this._emitEvent('modified', resource, { deletionPending: true });
      return resource;
    }

    const children = this.getChildren(uid);
    for (const child of children) {
      this.remove(child.uid);
    }

    this._removeFromKindIndex(resource);
    this._removeFromNamespaceIndex(resource);
    this._removeFromNameIndex(resource);
    this._removeFromLabelIndex(resource);

    const parents = this.reverseRelationships.get(uid);
    if (parents) {
      for (const parentUid of parents) {
        const parentRels = this.relationships.get(parentUid);
        if (parentRels) parentRels.delete(uid);
      }
    }

    const childRels = this.relationships.get(uid);
    if (childRels) {
      for (const childUid of childRels) {
        const reverseRels = this.reverseRelationships.get(childUid);
        if (reverseRels) reverseRels.delete(uid);
      }
    }

    this.relationships.delete(uid);
    this.reverseRelationships.delete(uid);
    this.resources.delete(uid);

    resource._deleted = true;
    this._emitEvent('deleted', resource);
    return resource;
  }

  get(uid) {
    return this.resources.get(uid) || null;
  }

  getByName(kind, name, namespace = 'default') {
    const key = `${kind}:${namespace}:${name}`;
    const uid = this.nameIndex.get(key);
    if (!uid) return null;
    return this.resources.get(uid) || null;
  }

  getByKind(kind) {
    const uids = this.kindIndex.get(kind);
    if (!uids) return [];
    const results = [];
    for (const uid of uids) {
      const r = this.resources.get(uid);
      if (r) results.push(r);
    }
    return results;
  }

  getResourcesByKind(kind) {
    return this.getByKind(kind);
  }

  getAllResources() {
    return Array.from(this.resources.values());
  }

  getResource(uid) {
    return this.resources.get(uid) || null;
  }

  getByNamespace(namespace) {
    const uids = this.namespaceIndex.get(namespace);
    if (!uids) return [];
    const results = [];
    for (const uid of uids) {
      const r = this.resources.get(uid);
      if (r) results.push(r);
    }
    return results;
  }

  getByKindAndNamespace(kind, namespace) {
    const kindUids = this.kindIndex.get(kind);
    if (!kindUids) return [];
    const nsUids = this.namespaceIndex.get(namespace);
    if (!nsUids) return [];
    const results = [];
    for (const uid of kindUids) {
      if (nsUids.has(uid)) {
        const r = this.resources.get(uid);
        if (r) results.push(r);
      }
    }
    return results;
  }

  query(options = {}) {
    let results = [];

    if (options.kind) {
      results = this.getByKind(options.kind);
    } else if (options.namespace) {
      results = this.getByNamespace(options.namespace);
    } else {
      results = Array.from(this.resources.values());
    }

    if (options.kind && options.namespace) {
      results = results.filter((r) => r.metadata.namespace === options.namespace);
    }

    if (options.selector) {
      results = results.filter((r) => r.matchesSelector(options.selector));
    }

    if (options.fieldSelector) {
      for (const [field, value] of Object.entries(options.fieldSelector)) {
        results = results.filter((r) => r.matchesFieldSelector(field, value));
      }
    }

    if (options.phase) {
      results = results.filter((r) => r.status.phase === options.phase);
    }

    if (options.name) {
      results = results.filter((r) => r.metadata.name.includes(options.name));
    }

    if (options.sortBy) {
      const key = options.sortBy;
      results.sort((a, b) => {
        const av = a.metadata[key] || a.status[key] || '';
        const bv = b.metadata[key] || b.status[key] || '';
        if (av < bv) return options.sortOrder === 'desc' ? 1 : -1;
        if (av > bv) return options.sortOrder === 'desc' ? -1 : 1;
        return 0;
      });
    }

    if (options.limit) {
      results = results.slice(0, options.limit);
    }

    return results;
  }

  selectByLabels(kind, selector) {
    const candidates = this.getByKind(kind);
    return candidates.filter((r) => r.matchesSelector(selector));
  }

  findPodsForService(serviceName, namespace = 'default') {
    const svc = this.getByName('Service', serviceName, namespace);
    if (!svc || !svc.spec.selector) return [];
    return this.selectByLabels('Pod', svc.spec.selector).filter(
      (p) => p.metadata.namespace === namespace
    );
  }

  findServiceForPod(podUid) {
    const pod = this.get(podUid);
    if (!pod) return [];
    const services = this.getByKindAndNamespace('Service', pod.metadata.namespace);
    return services.filter((svc) => {
      if (!svc.spec.selector) return false;
      return pod.matchesSelector(svc.spec.selector);
    });
  }

  getOwnerChain(uid) {
    const chain = [];
    let current = this.get(uid);
    while (current) {
      chain.unshift(current);
      const owner = current.getControllerOwner();
      if (!owner) break;
      current = this.get(owner.uid);
    }
    return chain;
  }

  getChildren(uid) {
    const childUids = this.relationships.get(uid);
    if (!childUids) return [];
    const results = [];
    for (const childUid of childUids) {
      const r = this.resources.get(childUid);
      if (r) results.push(r);
    }
    return results;
  }

  getDescendants(uid) {
    const descendants = [];
    const queue = [uid];
    const visited = new Set();
    while (queue.length > 0) {
      const currentUid = queue.shift();
      if (visited.has(currentUid)) continue;
      visited.add(currentUid);
      const children = this.getChildren(currentUid);
      for (const child of children) {
        descendants.push(child);
        queue.push(child.uid);
      }
    }
    return descendants;
  }

  getParents(uid) {
    const parentUids = this.reverseRelationships.get(uid);
    if (!parentUids) return [];
    const results = [];
    for (const parentUid of parentUids) {
      const r = this.resources.get(parentUid);
      if (r) results.push(r);
    }
    return results;
  }

  _addRelationship(parentUid, childUid) {
    let parentChildren = this.relationships.get(parentUid);
    if (!parentChildren) {
      parentChildren = new Set();
      this.relationships.set(parentUid, parentChildren);
    }
    parentChildren.add(childUid);

    let childParents = this.reverseRelationships.get(childUid);
    if (!childParents) {
      childParents = new Set();
      this.reverseRelationships.set(childUid, childParents);
    }
    childParents.add(parentUid);
  }

  addRelationship(parentUid, childUid) {
    this._addRelationship(parentUid, childUid);
    const child = this.get(childUid);
    const parent = this.get(parentUid);
    if (child && parent) {
      child.addOwnerReference(parent);
    }
  }

  _addToKindIndex(resource) {
    let set = this.kindIndex.get(resource.kind);
    if (!set) {
      set = new Set();
      this.kindIndex.set(resource.kind, set);
    }
    set.add(resource.uid);
  }

  _removeFromKindIndex(resource) {
    const set = this.kindIndex.get(resource.kind);
    if (set) set.delete(resource.uid);
  }

  _addToNamespaceIndex(resource) {
    const ns = resource.metadata.namespace || '';
    let set = this.namespaceIndex.get(ns);
    if (!set) {
      set = new Set();
      this.namespaceIndex.set(ns, set);
    }
    set.add(resource.uid);
  }

  _removeFromNamespaceIndex(resource) {
    const ns = resource.metadata.namespace || '';
    const set = this.namespaceIndex.get(ns);
    if (set) set.delete(resource.uid);
  }

  _addToNameIndex(resource) {
    const key = `${resource.kind}:${resource.metadata.namespace}:${resource.metadata.name}`;
    this.nameIndex.set(key, resource.uid);
  }

  _removeFromNameIndex(resource) {
    const key = `${resource.kind}:${resource.metadata.namespace}:${resource.metadata.name}`;
    this.nameIndex.delete(key);
  }

  _addToLabelIndex(resource) {
    for (const [key, value] of Object.entries(resource.metadata.labels)) {
      const indexKey = `${key}=${value}`;
      let set = this.labelIndex.get(indexKey);
      if (!set) {
        set = new Set();
        this.labelIndex.set(indexKey, set);
      }
      set.add(resource.uid);
    }
  }

  _removeFromLabelIndex(resource) {
    for (const [key, value] of Object.entries(resource.metadata.labels)) {
      const indexKey = `${key}=${value}`;
      const set = this.labelIndex.get(indexKey);
      if (set) set.delete(resource.uid);
    }
  }

  getByLabel(key, value) {
    const indexKey = `${key}=${value}`;
    const uids = this.labelIndex.get(indexKey);
    if (!uids) return [];
    const results = [];
    for (const uid of uids) {
      const r = this.resources.get(uid);
      if (r) results.push(r);
    }
    return results;
  }

  watch(kind, callback) {
    if (!this._watchCallbacks.has(kind)) {
      this._watchCallbacks.set(kind, []);
    }
    this._watchCallbacks.get(kind).push(callback);
    return () => {
      const list = this._watchCallbacks.get(kind);
      if (list) {
        this._watchCallbacks.set(
          kind,
          list.filter((cb) => cb !== callback)
        );
      }
    };
  }

  setResourceQuota(namespace, quota) {
    this.resourceQuotas.set(namespace, {
      hard: { ...quota },
      used: this._calculateQuotaUsage(namespace),
    });
  }

  getResourceQuota(namespace) {
    return this.resourceQuotas.get(namespace) || null;
  }

  _calculateQuotaUsage(namespace) {
    const pods = this.getByKindAndNamespace('Pod', namespace);
    let cpuUsed = 0;
    let memoryUsed = 0;
    let podCount = 0;

    for (const pod of pods) {
      if (pod.status.phase === 'Running' || pod.status.phase === 'Pending') {
        podCount++;
        const containers = pod.spec.containers || [];
        for (const c of containers) {
          const requests = (c.resources && c.resources.requests) || {};
          cpuUsed += this._parseCpu(requests.cpu || '0');
          memoryUsed += this._parseMemory(requests.memory || '0');
        }
      }
    }

    return { pods: podCount, cpu: cpuUsed, memory: memoryUsed };
  }

  checkQuota(namespace, requestedCpu, requestedMemory) {
    const quota = this.resourceQuotas.get(namespace);
    if (!quota) return { allowed: true };

    const usage = this._calculateQuotaUsage(namespace);
    const violations = [];

    if (quota.hard.cpu && usage.cpu + requestedCpu > quota.hard.cpu) {
      violations.push(`CPU quota exceeded: ${usage.cpu + requestedCpu}m > ${quota.hard.cpu}m`);
    }
    if (quota.hard.memory && usage.memory + requestedMemory > quota.hard.memory) {
      violations.push(`Memory quota exceeded: ${usage.memory + requestedMemory}Mi > ${quota.hard.memory}Mi`);
    }
    if (quota.hard.pods !== undefined) {
      const podCount = usage.pods + 1;
      if (podCount > quota.hard.pods) {
        violations.push(`Pod count exceeded: ${podCount} > ${quota.hard.pods}`);
      }
    }

    return {
      allowed: violations.length === 0,
      violations,
      usage,
    };
  }

  _parseCpu(value) {
    if (typeof value === 'number') return value;
    const str = String(value);
    if (str.endsWith('m')) return parseInt(str, 10);
    return parseFloat(str) * 1000;
  }

  _parseMemory(value) {
    if (typeof value === 'number') return value;
    const str = String(value);
    if (str.endsWith('Gi')) return parseFloat(str) * 1024;
    if (str.endsWith('Mi')) return parseFloat(str);
    if (str.endsWith('Ki')) return parseFloat(str) / 1024;
    return parseFloat(str) / (1024 * 1024);
  }

  getNodeAllocatable(nodeName) {
    const node = this.getByName('Node', nodeName, '');
    if (!node) return null;

    const cpuSpec = node.spec.cpu || node.capacity?.cpu || node.status.capacity?.cpu;
    const memSpec = node.spec.memory || node.capacity?.memory || node.status.capacity?.memory;
    const capacity = {
      cpu: cpuSpec ? this._parseCpu(cpuSpec) : 4000,
      memory: memSpec ? this._parseMemory(memSpec) : 8192,
    };
    const pods = this.getByKind('Pod').filter(
      (p) => p.spec.nodeName === nodeName && (p.status.phase === 'Running' || p.status.phase === 'Pending')
    );

    let cpuUsed = 0;
    let memoryUsed = 0;

    for (const pod of pods) {
      const containers = pod.spec.containers || [];
      for (const c of containers) {
        const requests = (c.resources && c.resources.requests) || {};
        cpuUsed += this._parseCpu(requests.cpu || '0');
        memoryUsed += this._parseMemory(requests.memory || '0');
      }
    }

    return {
      cpu: { capacity: capacity.cpu, used: cpuUsed, available: capacity.cpu - cpuUsed },
      memory: { capacity: capacity.memory, used: memoryUsed, available: capacity.memory - memoryUsed },
      podCount: pods.length,
    };
  }

  getClusterStats() {
    const nodes = this.getByKind('Node');
    const pods = this.getByKind('Pod');
    const deployments = this.getByKind('Deployment');
    const services = this.getByKind('Service');
    const namespaces = this.getByKind('Namespace');

    let totalCpu = 0;
    let usedCpu = 0;
    let totalMemory = 0;
    let usedMemory = 0;

    for (const node of nodes) {
      const alloc = this.getNodeAllocatable(node.name);
      if (alloc) {
        totalCpu += alloc.cpu.capacity;
        usedCpu += alloc.cpu.used;
        totalMemory += alloc.memory.capacity;
        usedMemory += alloc.memory.used;
      }
    }

    const podPhases = { Pending: 0, Running: 0, Succeeded: 0, Failed: 0, Unknown: 0 };
    for (const pod of pods) {
      const phase = pod.status.phase || 'Unknown';
      podPhases[phase] = (podPhases[phase] || 0) + 1;
    }

    return {
      nodes: { total: nodes.length, ready: nodes.filter((n) => n.isConditionTrue('Ready')).length },
      pods: { total: pods.length, ...podPhases },
      deployments: { total: deployments.length, available: deployments.filter((d) => d.isConditionTrue('Available')).length },
      services: { total: services.length },
      namespaces: { total: namespaces.length },
      resources: { total: this.resources.size },
      cpu: { total: totalCpu, used: usedCpu, percent: totalCpu > 0 ? Math.round((usedCpu / totalCpu) * 100) : 0 },
      memory: { total: totalMemory, used: usedMemory, percent: totalMemory > 0 ? Math.round((usedMemory / totalMemory) * 100) : 0 },
    };
  }

  getResourceGraph() {
    const nodes = [];
    const edges = [];

    for (const [uid, resource] of this.resources) {
      nodes.push({
        id: uid,
        kind: resource.kind,
        name: resource.metadata.name,
        namespace: resource.metadata.namespace,
        phase: resource.status.phase,
      });
    }

    for (const [parentUid, childUids] of this.relationships) {
      for (const childUid of childUids) {
        if (this.resources.has(parentUid) && this.resources.has(childUid)) {
          edges.push({ source: parentUid, target: childUid });
        }
      }
    }

    return { nodes, edges };
  }

  snapshot() {
    const data = {};
    for (const [uid, resource] of this.resources) {
      data[uid] = resource.toJSON();
    }
    return {
      timestamp: Date.now(),
      resourceCount: this.resources.size,
      resources: data,
    };
  }

  clear() {
    this.resources.clear();
    this.relationships.clear();
    this.reverseRelationships.clear();
    this.nameIndex.clear();
    this.labelIndex.clear();
    this.resourceQuotas.clear();
    this.limitRanges.clear();

    for (const [, set] of this.kindIndex) {
      set.clear();
    }
    for (const [, set] of this.namespaceIndex) {
      set.clear();
    }

    this._initDefaultNamespaces();

    if (this.eventBus) {
      this.eventBus.emit('cluster:reset', { timestamp: Date.now() });
    }
  }

  getExpectedChildKinds(kind) {
    return OWNER_CHAINS[kind] || [];
  }

  getAllKinds() {
    return [...RESOURCE_KINDS];
  }

  addResource(obj) {
    const ns = isClusterScopedKind(obj.kind) ? '' : (obj.metadata?.namespace || 'default');

    const resource = new ResourceBase(obj.kind, {
      name: obj.name || obj.metadata?.name || 'unnamed',
      namespace: ns,
      labels: obj.metadata?.labels || {},
      annotations: obj.metadata?.annotations || {},
    });
    if (obj.spec) {
      resource.spec = typeof obj.spec === 'object' ? { ...obj.spec } : {};
    }
    if (obj.status?.phase) {
      resource.setPhase(obj.status.phase);
    }
    return this.add(resource);
  }

  removeResource(kind, name, namespace = 'default') {
    const key = `${kind}:${namespace}:${name}`;
    const uid = this.nameIndex.get(key);
    if (uid) {
      return this.remove(uid);
    }
    return null;
  }
}

export default ClusterState;
